    class HingeDoorMotionObserver < Sketchup::EntityObserver
      def onChangeEntity(entity)
        UI.start_timer(0, false) do
          MHDESIGN::DressingDesigner.sync_hinge_accessories(entity) if entity && entity.valid?
        end
      rescue
