    def cloth_holder_definition(model)
      cached = @cloth_holder_definitions && @cloth_holder_definitions[model.object_id]
      return cached if cached && cached.valid?
      filename = 'cloth holder.skp'
      bundled = File.join(File.dirname(__FILE__), filename)
      definition = load_dressing_asset_definition(model, CLOTH_HOLDER_SKP_URL, filename, bundled)
      raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_7B18DBDFE034') unless definition
      claim_clean_definition_name(definition, 'إكسسوار ماسورة شماعة')
      definition.set_attribute('MHD_DRESSING', 'SOURCE_DEFINITION_NAME', 'إكسسوار ماسورة شماعة')
      set_part_badges(definition, ['HARDWARE','ACCESSORY','CLOTH_HOLDER'])
      definition.set_attribute('ladb_opencutlist', 'cumulable', 2)
      @cloth_holder_definitions ||= {}
      @cloth_holder_definitions[model.object_id] = definition
      definition
    end

    # يعزل هندسة ملف SKP عن أي Component Definitions داخلية مشتركة.
    # ملفات L و C قد تكون محفوظة من نفس الأصل، وبالتالي يمكن أن تحتوي على
    # nested definitions بنفس GUID حتى لو ملفا SKP نفسهما مختلفان. SketchUp
    # يدمج الـnested definition عند تحميل الملف الثاني، فيظهر القطاعان بنفس الشكل.
    # الحل: ننسخ كل ملف فور تحميله إلى Definition جديد ثم نفجر كل الـgroups/
    # component instances داخله إلى هندسة خام مستقلة قبل تحميل القطاع الآخر.
    def flatten_asset_definition(model, source_definition, clean_name, profile)
      raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_9432976876FB') unless source_definition && source_definition.valid?

      unique_name = clean_name.to_s
      begin
        old = model.definitions[unique_name]
        if old && old.valid? && old.instances.empty?
          model.definitions.remove(old) rescue nil
        end
      rescue
      end

      target = model.definitions.add(unique_name)
      wrapper = target.entities.add_instance(source_definition, Geom::Transformation.new)
      wrapper.explode if wrapper && wrapper.valid?

      # نفجر أي تعشيق داخلي حتى لا يبقى اعتماد على Definition مشترك بين L و C.
      12.times do
        nested = target.entities.grep(Sketchup::ComponentInstance) + target.entities.grep(Sketchup::Group)
        break if nested.empty?
        changed = false
        nested.each do |item|
          next unless item && item.valid?
          begin
            item.explode
            changed = true
          rescue
          end
        end
        break unless changed
      end

      raise "#{MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_0764D9B73C51')}#{profile}#{MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_70DAEA759D5D')}" if target.bounds.empty?
      target.set_attribute('MHD_DRESSING', 'SOURCE_DEFINITION_NAME', clean_name)
      target.set_attribute('MHD_DRESSING', 'GOLA_ASSET_PROFILE', profile)
      target.set_attribute('MHD_DRESSING', 'GOLA_ASSET_FLATTENED', true)
      set_part_badges(target, ['HARDWARE','ACCESSORY']) rescue nil
      target.set_attribute('ladb_opencutlist', 'cumulable', 2) rescue nil
      target
    end

    # يجمع الـDefinitions الداخلية التي يعتمد عليها ملف SKP المحمّل.
    # نستخدمه فقط لتنظيف تعريفات ملف الجولا المؤقتة بعد نسخ هندستها إلى تعريف مستقل.
    def collect_nested_asset_definitions(definition, result = {}, depth = 0)
      return result unless definition && definition.valid?
      return result if depth > 20
      definition.entities.grep(Sketchup::ComponentInstance).each do |instance|
        child = instance.definition rescue nil
        next unless child && child.valid?
        key = child.object_id
        next if result[key]
        result[key] = child
        collect_nested_asset_definitions(child, result, depth + 1)
      end
      definition.entities.grep(Sketchup::Group).each do |group|
        child = group.entities.parent rescue nil
        next unless child && child.respond_to?(:valid?) && child.valid?
        key = child.object_id
        next if result[key]
        result[key] = child
        collect_nested_asset_definitions(child, result, depth + 1)
      end
      result
    rescue
      result
    end

    # بعد ما نفجر ملف L إلى هندسة مستقلة، لازم نشيل تعريف المصدر وتعريفاته الداخلية
    # قبل تحميل C. الملفان معمولان من أصل واحد، وترك تعريفات L المؤقتة في الموديل
    # يجعل SketchUp يعيد استخدامها عند تحميل C (أو العكس).
    def cleanup_temporary_gola_source_definitions(model, source_definition, nested_hash)
      begin
        model.definitions.remove(source_definition) if source_definition && source_definition.valid? && source_definition.instances.empty?
      rescue
      end

      # من الأعمق للأعلى. لا نحذف أي تعريف ما زال له Instances، حماية لأي جزء مستخدم بالموديل.
      Array(nested_hash && nested_hash.values).reverse_each do |definition|
        next unless definition && definition.valid?
        begin
          model.definitions.remove(definition) if definition.instances.empty?
        rescue
        end
      end
      true
    end

    # تحميل L ثم عزله وتنظيف مصدره بالكامل، وبعدها فقط تحميل C.
    # بهذه الطريقة كل ملف يُقرأ بهندسته الأصلية ولا يستطيع SketchUp استبدال
    # nested definitions المشتركة بين الملفين.
    def ensure_biltin_gola_definitions(model)
      l_cached = @biltin_handle_definitions && @biltin_handle_definitions[model.object_id]
      c_cached = @biltin_handle_c_definitions && @biltin_handle_c_definitions[model.object_id]
      return [l_cached, c_cached] if l_cached && l_cached.valid? && c_cached && c_cached.valid?

      # 1) L أولاً
      l_filename = 'biltin hand.skp'
      l_bundled = File.join(File.dirname(__FILE__), l_filename)
      l_source = load_dressing_asset_definition(model, BILTIN_HANDLE_SKP_URL, l_filename, l_bundled)
      raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_2386B9B113F1') unless l_source && l_source.valid?
      l_nested = collect_nested_asset_definitions(l_source)
      l_definition = flatten_asset_definition(model, l_source, 'MHDESIGN GOLA METAL L ISOLATED', 'L')
      cleanup_temporary_gola_source_definitions(model, l_source, l_nested)

      # 2) C بعد إزالة كل تعريفات مصدر L المؤقتة
      c_filename = 'biltin hand c.skp'
      c_bundled = File.join(File.dirname(__FILE__), c_filename)
      c_source = load_dressing_asset_definition(model, BILTIN_HANDLE_C_SKP_URL, c_filename, c_bundled)
      raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_D7A6AAA54449') unless c_source && c_source.valid?
      c_nested = collect_nested_asset_definitions(c_source)
      c_definition = flatten_asset_definition(model, c_source, 'MHDESIGN GOLA METAL C ISOLATED', 'C')
      cleanup_temporary_gola_source_definitions(model, c_source, c_nested)

      @biltin_handle_definitions ||= {}
      @biltin_handle_c_definitions ||= {}
      @biltin_handle_definitions[model.object_id] = l_definition
      @biltin_handle_c_definitions[model.object_id] = c_definition
      [l_definition, c_definition]
    rescue => error
      raise "#{MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_AC09F1266CED')}#{error.message}"
    end

    def biltin_handle_definition(model)
      pair = ensure_biltin_gola_definitions(model)
      pair[0]
    end

    def biltin_handle_c_definition(model)
      pair = ensure_biltin_gola_definitions(model)
      pair[1]
    end

    def push_up_lift_definition(model)
      cached = @push_up_lift_definitions && @push_up_lift_definitions[model.object_id]
      return cached if cached && cached.valid?

      filename = 'push up lift.skp'
      bundled = File.join(File.dirname(__FILE__), filename)
      source = load_dressing_asset_definition(model, PUSH_UP_LIFT_SKP_URL, filename, bundled)
      raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_8928186EC14C') unless source

      # مهم جدًا:
      # لا نستخدم Definition ملف الـSKP نفسه مباشرة داخل الدولاب.
      # في أول إنشاء يكون شكله صحيح، لكن بعد تعديل الدولاب root.make_unique
      # ثم مراحل التسمية/الـDC قد تعيد التعامل مع الـDefinition المشتركة
      # ومكوناتها الداخلية، فيتغير شكل/موضع الباكم في الإنشاء التالي.
      #
      # نعمل نسخة "مخبوزة" Raw Geometry مرة واحدة، بنفس الأكسات والـOrigin
      # التي جهزها المصمم في push up lift.skp. بعدها لا يوجد DC داخلي أو
      # Child Definitions يمكن أن تتأثر بإعادة إنشاء الدولاب.
      internal_name = '__MHD_PUSH_UP_LIFT_BAKED_V1'
      baked = model.definitions[internal_name] || model.definitions.add(internal_name)

      if baked.entities.length == 0
        placed = baked.entities.add_instance(source, Geom::Transformation.new)
        placed.explode
        flatten_accessory_entities(baked.entities)
      end

      clean_name = 'باكم ضلفة قلاب'
      claim_clean_definition_name(baked, clean_name)
      baked.set_attribute('MHD_DRESSING', 'SOURCE_DEFINITION_NAME', clean_name)
      set_part_badges(baked, ['HARDWARE','ACCESSORY','PUSH_UP_LIFT'])
      baked.set_attribute('ladb_opencutlist', 'cumulable', 2)

      @push_up_lift_definitions ||= {}
      @push_up_lift_definitions[model.object_id] = baked
      baked
    end

