    # ============================================================
    # مكتبة الإكسسوارات والمقابض المخصصة — إعداد عام على الجهاز
    # ============================================================
    CUSTOM_ASSET_PREF_KEY = 'MHDESIGN_KITCHEN_CUSTOM_ASSETS_V1'.freeze
    CUSTOM_ASSET_PACKAGE_VERSION = 1

    DRESSING_LIBRARY_STATUS_URL = 'https://mhdesign-eg.com/wp-json/mhdesign-updater/v1/status'.freeze
    DRESSING_LIBRARY_PACKAGE_NAME = 'MHDESIGN_Dressing_ServerLibrary.mhassets'.freeze
    DRESSING_LIBRARY_PACKAGE_URL = "https://mhdesign-eg.com/SKETCHUP022/skp/dressing/#{DRESSING_LIBRARY_PACKAGE_NAME}".freeze
    DRESSING_LIBRARY_FORMAT = 'MHDESIGN_DRESSING_SERVER_LIBRARY'.freeze
    DRESSING_LIBRARY_LIMIT = 256 * 1024 * 1024
    DRESSING_LIBRARY_KINDS = {'interior'=>'Accessories', 'handles'=>'Handles', 'drawer_accessories'=>'DrawerAccessories'}.freeze

    def dressing_library_dir
      File.join(custom_asset_storage_dir, 'ServerLibrary')
    end

    def dressing_library_manifest
      path = File.join(dressing_library_dir, 'manifest.json')
      return {} unless File.file?(path)
      state = JSON.parse(File.binread(path).force_encoding('UTF-8'))
      state.is_a?(Hash) ? state : {}
    rescue JSON::ParserError, SystemCallError
      {}
    end

    def dressing_library_record_key(record)
      record['name'].to_s.strip.downcase
    end

    def dressing_library_personal_catalog(catalog, copy_overrides: false)
      personal = normalize_custom_asset_catalog(catalog.dup)
      root = File.expand_path(dressing_library_dir).downcase + File::SEPARATOR
      DRESSING_LIBRARY_KINDS.each_key do |kind|
        personal[kind] = personal[kind].filter_map do |record|
          next record unless record.is_a?(Hash)
          next if record['library_managed'] == true
          source = record['path'].to_s
          from_managed = File.expand_path(source).downcase.start_with?(root)
          next if from_managed && !(copy_overrides && record['library_copy'] == true)
          cleaned = record.reject { |key, _| key == 'library_copy' }
          if from_managed
            copied = copy_custom_asset_into_documents(source, kind)
            raise 'ملف الإكسسوار من المكتبة غير موجود.' unless copied
            cleaned['path'] = copied
          end
          cleaned
        end
      end
      personal
    end

    def dressing_library_managed_catalog(state = dressing_library_manifest)
      catalog = state['catalog'].is_a?(Hash) ? state['catalog'] : {}
      DRESSING_LIBRARY_KINDS.each_key.to_h do |kind|
        records = Array(catalog[kind]).select { |record| record.is_a?(Hash) && File.file?(record['path'].to_s) }
        [kind, records]
      end
    end

    def dressing_library_merge(personal, managed)
      merged = normalize_custom_asset_catalog(personal.dup)
      DRESSING_LIBRARY_KINDS.each_key do |kind|
        names = merged[kind].select { |record| record.is_a?(Hash) }.map { |record| dressing_library_record_key(record) }
        hidden = merged['library_hidden183']
        suppressed = hidden.is_a?(Hash) ? Array(hidden[kind]) : []
        excluded = names + suppressed
        merged[kind] += Array(managed[kind]).reject { |record| excluded.include?(dressing_library_record_key(record)) }
      end
      merged
    end

    def dressing_library_package_entry(name, bytes)
      {'name'=>name, 'sha256'=>Digest::SHA256.hexdigest(bytes), 'data'=>Base64.strict_encode64(bytes)}
    end

    class DressingLibraryConnectionError < StandardError; end

    class DressingLibraryHttpError < StandardError
      attr_reader :status

      def initialize(status)
        @status = status.to_i
        super("HTTP #{@status}")
      end
    end

    def dressing_library_http_get(url, limit)
      dressing_library_net_get(url, limit)
    rescue Net::OpenTimeout, Net::ReadTimeout, SocketError, SystemCallError
      jobs = @dressing_library_native_jobs
      raise unless jobs && defined?(Sketchup::Http::Request)
      reply = Queue.new
      jobs << [url, limit, reply]
      result = Timeout.timeout(40, Timeout::Error, 'انتهت مهلة تنزيل مكتبة الدريسنج داخل SketchUp.') { reply.pop }
      raise result if result.is_a?(Exception)
      result
    end

    # The SketchUp HTTP API starts on the UI thread; the worker waits for its result.
    def start_dressing_library_native_request(jobs, pending)
      return if jobs.empty?
      url, limit, reply = jobs.pop(true)
      request = Sketchup::Http::Request.new(url, Sketchup::Http::GET)
      request.headers = {'Cache-Control'=>'no-cache', 'User-Agent'=>'MHDESIGN-Dressing-Library'}
      pending[request] = true
      started = request.start do |_request, response|
        pending.delete(request)
        begin
          code = response.status_code.to_i
          raise DressingLibraryConnectionError, 'تعذر اتصال SketchUp بسيرفر مكتبة الدريسنج.' if code.zero?
          raise DressingLibraryHttpError.new(code) unless (200..299).cover?(code)
          bytes = response.body.to_s.b
          raise 'حزمة مكتبة الدريسنج أكبر من الحد المدعوم.' if bytes.bytesize > limit
          reply << bytes
        rescue StandardError => error
          reply << error
        end
      end
      raise 'تعذر بدء تنزيل مكتبة الدريسنج داخل SketchUp.' unless started
    rescue StandardError => error
      pending.delete(request) if request
      reply << error if reply
    end

    def dressing_library_net_get(url, limit)
      uri = URI(url)
      4.times do
        unless uri.is_a?(URI::HTTPS) && %w[mhdesign-eg.com www.mhdesign-eg.com].include?(uri.host.to_s.downcase) && uri.port == 443 && !uri.userinfo
          raise 'مسار تنزيل مكتبة الدريسنج غير صالح.'
        end
        http = Net::HTTP.new(uri.host, uri.port)
        http.use_ssl = true
        http.open_timeout = 6
        http.read_timeout = 15
        request = Net::HTTP::Get.new(uri.request_uri)
        request['Cache-Control'] = 'no-cache'
        request['User-Agent'] = 'MHDESIGN-Dressing-Library'
        bytes = ''.b
        redirect = nil
        http.request(request) do |response|
          if response.is_a?(Net::HTTPRedirection) && response['location']
            redirect = URI.join(uri.to_s, response['location'])
            next
          end
          raise DressingLibraryHttpError.new(response.code) unless response.is_a?(Net::HTTPSuccess)
          raise 'Dressing library response too large' if response['content-length'].to_i > limit
          response.read_body do |chunk|
            raise 'Dressing library response too large' if bytes.bytesize + chunk.bytesize > limit
            bytes << chunk.b
          end
        end
        return bytes unless redirect
        uri = redirect
      end
      raise 'تعذر الوصول لمسار حزمة الدريسنج بعد إعادة التوجيه.'
    end

    def dressing_library_fetch_update(applied_id, force: false)
      # A new installation obtains the static package without relying on WordPress.
      if applied_id.nil?
        raw = dressing_library_http_get(DRESSING_LIBRARY_PACKAGE_URL, DRESSING_LIBRARY_LIMIT)
        return ['bootstrap:' + Digest::SHA256.hexdigest(raw), validate_dressing_server_library(JSON.parse(raw))]
      end

      status = begin
        JSON.parse(dressing_library_http_get(DRESSING_LIBRARY_STATUS_URL, 64 * 1024))
      rescue StandardError
        raise unless force
        nil
      end
      announced = status.is_a?(Hash) && status['has_update'] == true && Array(status['targets']).include?('tools')
      update_id = announced ? status['update_id'].to_s.strip : ''
      if update_id.empty?
        return nil unless force
        update_id = applied_id
      end
      return nil if update_id == applied_id && !force
      query_values = {'update_id'=>update_id}
      query_values['refresh'] = SecureRandom.hex(8) if force
      query = URI.encode_www_form(query_values)
      raw = begin
        dressing_library_http_get("#{DRESSING_LIBRARY_PACKAGE_URL}?#{query}", DRESSING_LIBRARY_LIMIT)
      rescue DressingLibraryHttpError => error
        raise unless [400, 403, 404].include?(error.status)
        dressing_library_http_get(DRESSING_LIBRARY_PACKAGE_URL, DRESSING_LIBRARY_LIMIT)
      end
      [update_id, validate_dressing_server_library(JSON.parse(raw))]
    end

    def dressing_library_decode_entry(entry)
      raise 'Invalid dressing library file' unless entry.is_a?(Hash)
      bytes = Base64.strict_decode64(entry.fetch('data'))
      sha = Digest::SHA256.hexdigest(bytes)
      raise 'Invalid dressing library file checksum' unless bytes.bytesize > 100 && entry['sha256'] == sha
      [sha, bytes]
    end

    def validate_dressing_server_library(package)
      unless package.is_a?(Hash) && package['format'] == DRESSING_LIBRARY_FORMAT && package['version'] == 1 &&
             package['catalog'].is_a?(Hash) && package['files'].is_a?(Array) && package['server_cache'].is_a?(Array)
        raise 'Invalid dressing server library package'
      end
      files = {}
      package['files'].each do |entry|
        sha, bytes = dressing_library_decode_entry(entry)
        name = entry['name'].to_s
        unless DRESSING_LIBRARY_KINDS.values.any? { |folder| name == "#{folder}/#{sha}.skp" } && !files.key?(name)
          raise 'Invalid dressing library asset path'
        end
        files[name] = [sha, bytes]
      end
      catalog = {}
      DRESSING_LIBRARY_KINDS.each do |kind, folder|
        names = {}
        catalog[kind] = Array(package['catalog'][kind]).map do |record|
          raise 'Invalid dressing library asset record' unless record.is_a?(Hash)
          key = dressing_library_record_key(record)
          relative = record['path'].to_s
          if key.empty? || names[key] || !relative.start_with?(folder + '/') || !files.key?(relative)
            raise 'Invalid or duplicate dressing library asset record'
          end
          names[key] = true
          record
        end
      end
      cache = {}
      package['server_cache'].each do |entry|
        sha, bytes = dressing_library_decode_entry(entry)
        name = entry['name'].to_s
        raise 'Invalid dressing library cache name' unless name.match?(/\Askp_[0-9a-f]{64}\.cache\z/) && !cache.key?(name)
        cache[name] = [sha, bytes]
      end
      {catalog: catalog, files: files, cache: cache}
    end

    def dressing_library_atomic_write(path, bytes)
      temp = File.join(File.dirname(path), ".mhlib-#{Process.pid}-#{SecureRandom.hex(6)}.tmp")
      File.open(temp, 'wb') do |file|
        file.write(bytes)
        file.flush
        file.fsync
      end
      File.rename(temp, path)
    ensure
      File.delete(temp) if temp && File.file?(temp)
    end

    def apply_dressing_server_library(update_id, package, expected_id, force: false)
      root = dressing_library_dir
      FileUtils.mkdir_p(root)
      File.open(File.join(root, 'sync.lock'), 'a+b') do |lock|
        lock.flock(File::LOCK_EX)
        state = dressing_library_manifest
        return false if state['update_id'] != expected_id
        return false if state['update_id'] == update_id && !force
        catalog = dressing_library_managed_catalog(state)
        cache_files = state['cache_files'].is_a?(Hash) ? state['cache_files'].dup : {}
        assets_dir = File.join(root, 'assets')
        cache_dir = File.join(root, 'cache')
        FileUtils.mkdir_p([assets_dir, cache_dir])
        paths = {}
        package.fetch(:files).each do |relative, (sha, bytes)|
          target = File.join(assets_dir, "#{sha}.skp")
          dressing_library_atomic_write(target, bytes) unless File.file?(target) && Digest::SHA256.file(target).hexdigest == sha
          paths[relative] = target
        end
        package.fetch(:catalog).each do |kind, records|
          by_name = catalog.fetch(kind).to_h { |record| [dressing_library_record_key(record), record] }
          records.each do |record|
            by_name[dressing_library_record_key(record)] = record.merge('path'=>paths.fetch(record['path']), 'library_managed'=>true)
          end
          catalog[kind] = by_name.values
        end
        package.fetch(:cache).each do |name, (_sha, bytes)|
          encrypted = encrypt_dressing_cache_bytes(bytes)
          file = "#{Digest::SHA256.hexdigest(encrypted)}.cache"
          dressing_library_atomic_write(File.join(cache_dir, file), encrypted)
          cache_files[name] = file
        end
        updated = {'update_id'=>update_id, 'catalog'=>catalog, 'cache_files'=>cache_files}
        dressing_library_atomic_write(File.join(root, 'manifest.json'), JSON.generate(updated))
      end
      if !package.fetch(:cache).empty?
        %i[@butterfly_definitions @shelf_support_definitions @elita_definitions @cloth_holder_definitions
           @biltin_handle_definitions @biltin_handle_c_definitions @push_up_lift_definitions
           @drawer_slide_left_definitions @drawer_slide_right_definitions @drawer_slide_pair_definitions
           @drawer_under_slide_definitions141 @right_drawer_slide_aligned_definitions @recessed_handle_definitions132
           @hinge_accessory_definitions @hinge_180_accessory_definitions @hinge_knee_accessory_definitions].each do |name|
          instance_variable_set(name, {})
        end
      end
      true
    end

    def read_managed_dressing_asset_cache(url)
      cache = dressing_library_manifest['cache_files']
      return nil unless cache.is_a?(Hash)
      name = File.basename(dressing_asset_cache_file_for_url(url))
      file = cache[name]
      return nil unless file.to_s.match?(/\A[0-9a-f]{64}\.cache\z/)
      path = File.join(dressing_library_dir, 'cache', file)
      return nil unless File.file?(path)
      decrypt_dressing_cache_bytes(File.binread(path))
    rescue StandardError
      nil
    end

    def dressing_library_missing_assets?(state)
      catalog = state['catalog']
      return false unless catalog.is_a?(Hash)
      DRESSING_LIBRARY_KINDS.keys.any? do |kind|
        Array(catalog[kind]).any? { |record| record.is_a?(Hash) && !File.file?(record['path'].to_s) }
      end
    end

    def update_dressing_library_status(message)
      @dressing_library_status = message
      @dialog.execute_script("window.setDressingLibraryStatus186(#{JSON.generate(message)})") if @dialog && @dressing_library_dialog_ready
    rescue StandardError => error
      puts "MHDESIGN Dressing library status display skipped: #{error.message}"
    end

    def dressing_library_retryable_error?(error)
      return [408, 429].include?(error.status) || error.status >= 500 if error.is_a?(DressingLibraryHttpError)
      error.is_a?(Timeout::Error) || error.is_a?(SocketError) || error.is_a?(SystemCallError) ||
        error.is_a?(DressingLibraryConnectionError)
    end

    def start_dressing_library_sync(manual: false, retry_once: true)
      if @dressing_library_worker
        UI.messagebox('مزامنة مكتبة الدريسنج شغالة بالفعل.') if manual
        return
      end
      state = dressing_library_manifest
      applied_id = state['update_id']
      force = manual || dressing_library_missing_assets?(state)
      update_dressing_library_status('جاري فحص مكتبة السيرفر…')
      jobs = Queue.new
      pending = {}
      @dressing_library_native_jobs = jobs
      worker = Thread.new do
        begin
          dressing_library_fetch_update(applied_id, force: force)
        rescue StandardError => error
          error
        end
      end
      @dressing_library_worker = worker
      timer = UI.start_timer(0.25, true) do
        if worker.alive?
          start_dressing_library_native_request(jobs, pending)
          next
        end
        UI.stop_timer(timer)
        pending.keys.each { |request| request.cancel rescue nil }
        @dressing_library_native_jobs = nil
        @dressing_library_worker = nil
        begin
          result = worker.value
          raise result if result.is_a?(Exception)
          if result
            apply_dressing_server_library(*result, applied_id, force: force)
            catalog = dressing_library_managed_catalog
            if @dialog && @dressing_library_dialog_ready
              @dialog.execute_script("window.applyManagedDressingLibrary183(#{JSON.generate(catalog)})")
            end
            total = catalog.values.sum(&:size)
            message = "مكتبة السيرفر: #{total} عنصر، منها #{catalog.fetch('handles').size} مقبض."
            update_dressing_library_status(message)
            UI.messagebox(message) if manual
          else
            update_dressing_library_status('مكتبة السيرفر محدثة.')
          end
        rescue StandardError => error
          puts "MHDESIGN Dressing library apply skipped: #{error.message}"
          if retry_once && dressing_library_retryable_error?(error) && @dialog
            update_dressing_library_status('الاتصال بمكتبة السيرفر تعذر. جاري إعادة المحاولة تلقائيًا…')
            dialog = @dialog
            UI.start_timer(2.0, false) do
              start_dressing_library_sync(manual: manual, retry_once: false) if @dialog.equal?(dialog)
            end
          else
            update_dressing_library_status("تعذر تحميل مكتبة السيرفر: #{error.message}")
            UI.messagebox("تعذر مزامنة مكتبة الدريسنج: #{error.message}") if manual
          end
        end
      end
    rescue StandardError => error
      @dressing_library_worker = nil
      puts "MHDESIGN Dressing library sync could not start: #{error.message}"
      update_dressing_library_status("تعذر بدء تحميل مكتبة السيرفر: #{error.message}")
    end

    def apply_imported_dressing_server_library(package, bytes)
      raise 'حزمة مكتبة الدريسنج أكبر من الحد المدعوم.' if bytes.bytesize > DRESSING_LIBRARY_LIMIT
      package = validate_dressing_server_library(package)
      previous = dressing_library_manifest['update_id']
      # A local import does not mark a WordPress release as downloaded.
      update_id = previous || 'bootstrap:' + Digest::SHA256.hexdigest(bytes)
      raise 'المكتبة اتحدثت أثناء الاستيراد. جرّب تاني.' unless apply_dressing_server_library(update_id, package, previous, force: true)
      catalog = dressing_library_managed_catalog
      @dialog.execute_script("window.applyManagedDressingLibrary183(#{JSON.generate(catalog)})") if @dialog
      message = "تم استيراد حزمة السيرفر: #{catalog.values.sum(&:size)} عنصر، منها #{catalog.fetch('handles').size} مقبض."
      update_dressing_library_status(message)
      UI.messagebox(message)
    rescue StandardError => error
      UI.messagebox("تعذر استيراد حزمة السيرفر: #{error.message}")
    end

    def custom_asset_storage_dir
      home = ENV['USERPROFILE'].to_s.strip
      home = Dir.home.to_s if home.empty? && Dir.respond_to?(:home)
      dir = File.expand_path(File.join(home, 'Documents', 'MHDESIGN', 'CustomAssets'))
      FileUtils.mkdir_p(dir)
      FileUtils.mkdir_p(File.join(dir, 'Accessories'))
      FileUtils.mkdir_p(File.join(dir, 'Handles'))
      dir
    end

    def custom_asset_kind_dir(kind)
      folder = {'handles'=>'Handles','drawer_accessories'=>'DrawerAccessories'}[kind.to_s] || 'Accessories'
      dir = File.join(custom_asset_storage_dir, folder)
      FileUtils.mkdir_p(dir)
      dir
    end

    def custom_asset_catalog_file
      File.join(custom_asset_storage_dir, 'custom_assets.json')
    end

    def normalize_custom_asset_catalog(value)
      catalog = value.is_a?(Hash) ? value : {}
      catalog['interior'] = [] unless catalog['interior'].is_a?(Array)
      catalog['handles'] = [] unless catalog['handles'].is_a?(Array)
      catalog['drawer_accessories'] = [] unless catalog['drawer_accessories'].is_a?(Array)
      catalog
    end

    def custom_asset_catalogs
      dressing_library_merge(local_custom_asset_catalogs, dressing_library_managed_catalog)
    end

    def local_custom_asset_catalogs
      path = custom_asset_catalog_file
      return normalize_custom_asset_catalog({}) unless File.file?(path)
      parsed = JSON.parse(File.binread(path).force_encoding('UTF-8'))
      normalize_custom_asset_catalog(parsed)
    rescue => error
      puts "MHDESIGN load custom asset catalog failed: #{error.class}: #{error.message}"
      normalize_custom_asset_catalog({})
    end

    def portable_asset_filename(source)
      ext = File.extname(source.to_s)
      base = File.basename(source.to_s, ext).gsub(/[^0-9A-Za-z_\-\u0600-\u06FF ]/, '_').strip
      base = 'asset' if base.empty?
      "#{base}_#{Digest::SHA256.file(source.to_s).hexdigest[0,10]}.skp"
    end

    def copy_custom_asset_into_documents(source, kind)
      return nil unless File.file?(source.to_s)
      raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_DF763391782F') unless File.extname(source.to_s).downcase == '.skp'
      target = File.join(custom_asset_kind_dir(kind), portable_asset_filename(source))
      unless File.expand_path(source.to_s).downcase == File.expand_path(target).downcase
        same = File.file?(target) &&
               Digest::SHA256.file(target).hexdigest == Digest::SHA256.file(source.to_s).hexdigest
        FileUtils.cp(source.to_s, target) unless same
      end
      target
    end

    def save_custom_asset_catalogs(value)
      catalog = dressing_library_personal_catalog(value.is_a?(Hash) ? value : {}, copy_overrides: true)
      {'interior'=>'interior', 'handles'=>'handles', 'drawer_accessories'=>'drawer_accessories'}.each do |key, kind|
        Array(catalog[key]).each do |record|
          next unless record.is_a?(Hash)
          source = record['path'].to_s
          next if source.empty? || !File.file?(source)
          root = File.expand_path(custom_asset_kind_dir(kind)).downcase
          current = File.expand_path(source).downcase
          unless current.start_with?(root + File::SEPARATOR.downcase)
            copied = copy_custom_asset_into_documents(source, kind)
            record['path'] = copied if copied
          end
        end
      end

      json = JSON.pretty_generate(catalog)
      path = custom_asset_catalog_file
      tmp = path + '.tmp'
      File.open(tmp, 'wb') { |f| f.write(json.encode('UTF-8')); f.flush; f.fsync rescue nil }
      File.delete(path) if File.file?(path)
      File.rename(tmp, path)
      Sketchup.write_default(CUSTOM_ASSET_PREF_KEY, 'catalog_json', JSON.generate(catalog)) rescue nil
      catalog
    rescue => error
      begin File.delete(tmp) if defined?(tmp) && File.file?(tmp) rescue nil end
      puts "MHDESIGN save custom asset catalog failed: #{error.class}: #{error.message}"
      raise error
    end

    def import_custom_skp_file(kind = 'interior')
      title = kind.to_s == 'handles' ? 'اختيار ملف المقبض SKP' : 'اختيار ملف الإكسسوار SKP'
      source = UI.openpanel(title, '', 'SketchUp Model|*.skp||')
      return nil if source.to_s.empty? || !File.file?(source)
      target = copy_custom_asset_into_documents(source, kind)
      {'path'=>target, 'filename'=>File.basename(source)}
    end

    def export_custom_asset_package(settings_snapshot = nil)
      catalog = local_custom_asset_catalogs
      packed_catalog = Marshal.load(Marshal.dump(catalog))
      if settings_snapshot.is_a?(Hash)
        keys = %w[naming_dictionary carcass_board_width carcass_board_length door_board_width door_board_length back_board_width back_board_length edge_band_pattern]
        packed_catalog['library_settings135'] = settings_snapshot.select { |k,_| keys.include?(k) }
      end
      cached_files = Dir.glob(File.join(dressing_units_cache_root_dir, 'skp_*.cache')).sort.map do |file|
        bytes = File.binread(file)
        decrypt_dressing_cache_bytes(bytes) # Do not silently export a broken or foreign cache.
        {'name'=>File.basename(file),'sha256'=>Digest::SHA256.hexdigest(bytes),'data'=>Base64.strict_encode64(bytes)}
      end
      packed_files = []
      {'interior'=>'Accessories', 'handles'=>'Handles', 'drawer_accessories'=>'DrawerAccessories'}.each do |key, folder|
        Array(packed_catalog[key]).each do |record|
          next unless record.is_a?(Hash)
          source = record['path'].to_s
          raise "ملف المكتبة غير موجود: #{record['name']}" unless File.file?(source)
          rel = "#{folder}/#{File.basename(source)}"
          bytes = File.binread(source)
          packed_files << {'name'=>rel, 'sha256'=>Digest::SHA256.hexdigest(bytes),
                           'data'=>Base64.strict_encode64(bytes)}
          record['path'] = rel
        end
      end
      package = {'format'=>'MHDESIGN_CUSTOM_ASSETS',
                 'version'=>CUSTOM_ASSET_PACKAGE_VERSION,
                 'catalog'=>packed_catalog, 'files'=>packed_files, 'server_cache'=>cached_files, 'full_library_version'=>1}
      target = UI.savepanel('تصدير مكتبة MHDESIGN', '',
                            "MHDESIGN_FullLibrary_#{Time.now.strftime('%Y%m%d')}.mhassets")
      return nil if target.to_s.empty?
      target += '.mhassets' if File.extname(target).empty?
      File.binwrite(target, JSON.generate(package))
      target
    end

    def import_custom_asset_package
      source = UI.openpanel('استيراد مكتبة MHDESIGN', '', 'MHDESIGN Assets|*.mhassets||')
      return nil if source.to_s.empty? || !File.file?(source)
      bytes = File.binread(source)
      package = JSON.parse(bytes.dup.force_encoding('UTF-8'))
      if package.is_a?(Hash) && package['format'] == DRESSING_LIBRARY_FORMAT
        apply_imported_dressing_server_library(package, bytes)
        return nil
      end
      raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_BAE62B6776FC') unless package['format'].to_s == 'MHDESIGN_CUSTOM_ASSETS'

      cache_restore = Array(package['server_cache']).map do |entry|
        raise 'بيانات الكاش غير سليمة.' unless entry.is_a?(Hash)
        name = entry['name'].to_s
        raise 'اسم ملف الكاش غير سليم.' unless name.match?(/\Askp_[0-9a-f]{64}\.cache\z/)
        bytes = Base64.strict_decode64(entry['data'].to_s)
        raise 'ملف الكاش تالف.' unless Digest::SHA256.hexdigest(bytes) == entry['sha256'].to_s
        begin
          decrypt_dressing_cache_bytes(bytes)
        rescue
          raise 'الكاش مش متوافق مع الجهاز أو بيانات التفعيل الحالية. استورده بنفس الجهاز وبيانات التفعيل اللي اتصدّر بيها.'
        end
        [name,bytes]
      end
      Array(package['files']).each do |entry|
        raise 'بيانات ملف المكتبة غير سليمة.' unless entry.is_a?(Hash)
        rel = entry['name'].to_s.tr('\\','/')
        raise 'مسار ملف المكتبة غير سليم.' unless rel.match?(/\A(?:Handles|Accessories|DrawerAccessories)\/[^\/]+\.skp\z/i) && !rel.include?('..') && !rel.include?(':')
        bytes = Base64.strict_decode64(entry['data'].to_s)
        expected = entry['sha256'].to_s
        raise 'ملف المكتبة تالف.' unless expected.empty? || Digest::SHA256.hexdigest(bytes) == expected
      end
      file_map = {}
      Array(package['files']).each do |entry|
        next unless entry.is_a?(Hash)
        rel = entry['name'].to_s.tr('\\','/')
        kind = rel.start_with?('DrawerAccessories/') ? 'drawer_accessories' : (rel.start_with?('Handles/') ? 'handles' : 'interior')
        filename = File.basename(rel)
        raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_546BCF1EE6A0') unless File.extname(filename).downcase == '.skp'
        bytes = Base64.strict_decode64(entry['data'].to_s)
        sha = Digest::SHA256.hexdigest(bytes)
        expected = entry['sha256'].to_s
        raise "#{MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_E2B40627F00D')}#{filename}#{MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_4254D0D2A3BC')}" unless expected.empty? || expected == sha
        target = File.join(custom_asset_kind_dir(kind), filename)
        File.binwrite(target, bytes) unless File.file?(target) &&
          Digest::SHA256.file(target).hexdigest == sha
        file_map[rel] = target
      end

      incoming = normalize_custom_asset_catalog(package['catalog'])
      %w[interior handles drawer_accessories].each do |key|
        Array(incoming[key]).each do |record|
          next unless record.is_a?(Hash)
          rel = record['path'].to_s.tr('\\','/')
          record['path'] = file_map[rel] if file_map[rel]
        end
      end

      current = normalize_custom_asset_catalog(local_custom_asset_catalogs)
      %w[interior handles drawer_accessories].each do |key|
        Array(incoming[key]).each do |record|
          next unless record.is_a?(Hash) && File.file?(record['path'].to_s)
          name = record['name'].to_s.strip
          next if name.empty?
          idx = current[key].index { |r| r.is_a?(Hash) && r['name'].to_s.strip.downcase == name.downcase }
          idx ? current[key][idx] = record : current[key] << record
        end
      end
      incoming.each { |key,value| current[key] = value unless %w[interior handles drawer_accessories].include?(key) }
      saved = save_custom_asset_catalogs(current)
      cache_restore.each do |name,bytes|
        target = File.join(dressing_units_cache_root_dir,name)
        temp = target + ".restore_#{Process.pid}"
        begin
          File.binwrite(temp,bytes)
          FileUtils.mv(temp,target,force:true)
        ensure
          File.delete(temp) if File.file?(temp)
        end
      end
      @recessed_handle_definitions132 = {}
      @custom_asset_definitions = {}
      dressing_library_merge(saved, dressing_library_managed_catalog)
    end

    def custom_asset_definition(model, path, clean_name = nil)
      return nil if path.to_s.empty? || !File.file?(path.to_s)
      @custom_asset_definitions ||= {}
      key = [model.object_id, File.expand_path(path.to_s)]
      definition = @custom_asset_definitions[key]
      return definition if definition && definition.valid?
      definition = model.definitions.load(path.to_s)
      return nil unless definition
      if clean_name && !clean_name.to_s.strip.empty?
        begin
          claim_clean_definition_name(definition, clean_name.to_s.strip)
        rescue
          definition.name = clean_name.to_s.strip rescue nil
        end
      end
      @custom_asset_definitions[key] = definition
      definition
    rescue => error
      puts "MHDESIGN custom asset load failed: #{error.message}"
      nil
    end

    def active_normal_handle_record
      return nil unless active_handle_type == 'normal'
      data = @active_design_data.is_a?(Hash) ? @active_design_data : {}
      handles = custom_asset_catalogs['handles'].select { |item| item.is_a?(Hash) }
      wanted = active_front_handle_value('normal_handle_name', '').to_s.strip

      # UX safety: لو العميل عنده مقبض واحد فقط ولم يختر الاسم من الليستة
      # نعتبره هو المقبض النشط تلقائيًا بدل أن نسكت ولا نركب شيئًا.
      if wanted.empty? && handles.length == 1
        wanted = handles.first['name'].to_s.strip
        data['normal_handle_name'] = wanted unless wanted.empty?
      end
      return nil if wanted.empty?

      record = handles.find { |item| item['name'].to_s.strip == wanted }
      raise "#{MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_FC37CCFEC254')}#{wanted}#{MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_09851B3E5AA4')}" unless record
      path = record['path'].to_s
      raise "#{MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_98635F41EE3C')}#{wanted}#{MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_9365E018A4E8')}" if path.empty? || !File.file?(path)
      record
    end

    def active_normal_handle_unit_type
      value = active_front_handle_value('normal_handle_unit_type', 'lower').to_s
      %w[upper lower wardrobe].include?(value) ? value : 'lower'
    end

    def stamp_custom_accessory(instance, name, kind)
      return unless instance && instance.valid?
      instance.name = name.to_s unless name.to_s.empty?
      [instance, instance.definition].each do |owner|
        owner.set_attribute('MHD_DRESSING', 'CUSTOM_ACCESSORY', true)
        owner.set_attribute('MHD_DRESSING', 'CUSTOM_ACCESSORY_NAME', name.to_s)
        owner.set_attribute('MHD_DRESSING', 'CUSTOM_ACCESSORY_KIND', kind.to_s)
      end
      set_part_badges(instance, ['HARDWARE','ACCESSORY', kind.to_s.upcase]) rescue nil
      instance.definition.set_attribute('ladb_opencutlist', 'cumulable', 2) rescue nil
      instance
    end

    # تركيب المقبض المخصص لا يعتمد على Origin ملف الـSKP.
    # مهم: المقبض لا يدخل داخل Definition الضلفة/وش الدرج نفسه، حتى لا يوسّع
    # Bounding Box الخاص بقطعة الخشب ويغيّر مقاسها في OpenCutList.
    # لذلك نضيفه كعنصر شقيق في نفس الـParent، ثم نربطه بحركة الضلفة عند الحاجة.
    def force_custom_asset_visible!(instance)
      return unless instance && instance.valid?
      begin instance.hidden = false rescue nil end
      begin instance.layer = Sketchup.active_model.layers[0] rescue nil end
      [instance, instance.definition].each do |owner|
        begin owner.set_attribute('dynamic_attributes', 'hidden', '0') rescue nil end
        begin owner.set_attribute('dynamic_attributes', '_hidden_formula', 'FALSE') rescue nil end
        begin owner.set_attribute('dynamic_attributes', '_inst__hidden_formula', 'FALSE') rescue nil end
      end
      instance.definition.entities.each do |entity|
        begin entity.hidden = false if entity.respond_to?(:hidden=) rescue nil end
        begin entity.layer = Sketchup.active_model.layers[0] if entity.respond_to?(:layer=) rescue nil end
      end
    rescue
      nil
    end

    def front_parent_entities(front_instance)
      parent = front_instance.parent rescue nil
      return parent.entities if parent && parent.respond_to?(:entities)
      nil
    rescue
      nil
    end

    # يركب المقبض كـSibling للواجهة، لا كطفل داخل تعريف الواجهة.
    # edge_mode:
    #   :left  => أول جسم المقبض يبعد عن الحد الشمال بالقيمة المحددة.
    #   :right => آخر جسم المقبض يبعد عن الحد اليمين بالقيمة المحددة.
    # vertical_mode:
    #   :top    => أعلى جسم المقبض يبعد عن أعلى الواجهة بالقيمة المحددة.
    #   :bottom => أسفل جسم المقبض يبعد عن أسفل الواجهة بالقيمة المحددة.
    #   :center => مركز المقبض = مركز ارتفاع الواجهة.
    # تركيب المقبض داخل Definition الواجهة نفسها — نفس منطق الكود المرجعي.
    # بهذه الطريقة المقبض يصبح جزءًا من حركة الضلفة/وش الدرج نفسها، وبالتالي
    # يفتح ويقفل معها في نفس الفريم بدون Observer يلحق بها بعد الحركة.
    def mount_custom_handle_on_front(front_instance, definition, kind, name,
                                     edge_mode: nil, edge_offset: 0.0,
                                     vertical_mode: :center, vertical_offset: 0.0,
                                     center_x_offset: 0.0, center_z_offset: 0.0,
                                     rotation_x_deg: 0.0, rotation_y_deg: 0.0, rotation_z_deg: 0.0,
                                     move_x: 0.0, move_y: 0.0, move_z: 0.0,
                                     rigid_follow: false, extra_attrs: {})
      raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_DE7E8C3C3E24') unless front_instance && front_instance.valid?
      raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_24BFB04ACFD8') unless definition && definition.valid?

      parent_bounds = front_instance.definition.bounds
      # دوران حر على المحاور الثلاثة. الصفر على المحاور كلها = نفس اتجاه ملف SKP كما هو.
      # نطبق X ثم Y ثم Z، والقيم تقبل الموجب والسالب بدون أي تقييد.
      rx = Geom::Transformation.rotation(ORIGIN, X_AXIS, rotation_x_deg.to_f.degrees)
      ry = Geom::Transformation.rotation(ORIGIN, Y_AXIS, rotation_y_deg.to_f.degrees)
      rz = Geom::Transformation.rotation(ORIGIN, Z_AXIS, rotation_z_deg.to_f.degrees)
      rotation = rz * ry * rx
      child = front_instance.definition.entities.add_instance(definition, rotation)
      raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_58EA3C155879') unless child && child.valid?
      force_custom_asset_visible!(child)

      cb = child.bounds
      raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_7A24E4989C8C') if cb.empty?

      # ---------- العرض ----------
      dx = case edge_mode
           when :left
             desired_min = parent_bounds.min.x.to_f + edge_offset.to_f
             desired_min - cb.min.x.to_f
           when :right
             desired_max = parent_bounds.max.x.to_f - edge_offset.to_f
             desired_max - cb.max.x.to_f
           else
             (parent_bounds.center.x.to_f + center_x_offset.to_f) - cb.center.x.to_f
           end

      # ---------- الارتفاع ----------
      # 0 فقط = توسيط. غير ذلك المسافة من حافة جسم المقبض نفسها.
      dz = case vertical_mode
           when :top
             desired_max = parent_bounds.max.z.to_f - vertical_offset.to_f
             desired_max - cb.max.z.to_f
           when :bottom
             desired_min = parent_bounds.min.z.to_f + vertical_offset.to_f
             desired_min - cb.min.z.to_f
           else
             (parent_bounds.center.z.to_f + center_z_offset.to_f) - cb.center.z.to_f
           end

      # أمام وش الواجهة، بالاعتماد على جسم المقبض لا Origin الملف.
      desired_front_y = parent_bounds.min.y.to_f - 0.30.cm
      dy = desired_front_y - cb.max.y.to_f
      child.transform!(Geom::Transformation.translation([
        dx + move_x.to_f,
        dy + move_y.to_f,
        dz + move_z.to_f
      ]))
      force_custom_asset_visible!(child)

      stamp_custom_accessory(child, name, kind)
      child.set_attribute('MHD_DRESSING', 'HANDLE_MOUNT_OK', true)
      child.set_attribute('MHD_DRESSING', 'HANDLE_MOTION_MODE', 'NESTED_WITH_FRONT')
      child.set_attribute('MHD_DRESSING', 'HANDLE_EDGE_MODE', edge_mode.to_s)
      child.set_attribute('MHD_DRESSING', 'HANDLE_EDGE_OFFSET_CM', edge_offset.to_f / 1.cm.to_f)
      child.set_attribute('MHD_DRESSING', 'HANDLE_VERTICAL_MODE', vertical_mode.to_s)
      child.set_attribute('MHD_DRESSING', 'HANDLE_VERTICAL_OFFSET_CM', vertical_offset.to_f / 1.cm.to_f)
      extra_attrs.each { |key, value| child.set_attribute('MHD_DRESSING', key.to_s, value) }
      child
    rescue => error
      puts "MHDESIGN custom handle mount failed: #{error.class}: #{error.message}"
      raise error
    end

    # أبقينا الدالة للتوافق مع أي وحدة قديمة، لكن المقابض الجديدة لا تحتاجها؛
    # الحركة تأتي من كون المقبض داخل Definition الواجهة نفسها.
    def register_rigid_front_motion(front, accessory)
      accessory
    end

    # الضلفة يمين: المقبض ناحية الشمال، ولذلك المسافة تدخل به من الشمال ناحية اليمين.
    # الضلفة شمال: المقبض ناحية اليمين، ولذلك المسافة تدخل به من اليمين ناحية الشمال.
    # نوع الوحدة يحدد مرجع الارتفاع:
    #   سفلية = من أعلى الضلفة لأسفل.
    #   علوية = من أسفل الضلفة لأعلى.
    # والمسافة 0 وحدها تعني توسيط المقبض رأسيًا.
    def normal_handle_case_settings(record, case_name)
      drawer = case_name.to_s == 'drawer'
      flap = case_name.to_s == 'flap'
      wardrobe = case_name.to_s == 'wardrobe'
      upper = case_name.to_s == 'upper'

      defaults = {
        'horizontal_reference' => drawer || flap ? 'center' : 'auto',
        'horizontal_cm' => drawer ? record['drawer_x_offset'].to_f : record['door_edge_offset'].to_f,
        'vertical_reference' => wardrobe || drawer ? 'center' : (upper || flap ? 'bottom' : 'top'),
        'vertical_cm' => wardrobe ? 0.0 : (drawer ? record['drawer_z_offset'].to_f : record['door_vertical_offset'].to_f),
        'move_x_cm' => 0.0, 'move_y_cm' => 0.0, 'move_z_cm' => 0.0,
        'rot_x' => drawer ? record['drawer_rotation_x_deg'].to_f : record['door_rotation_x_deg'].to_f,
        'rot_y' => drawer ? (record.key?('drawer_rotation_y_deg') ? record['drawer_rotation_y_deg'].to_f : record['drawer_rotation_deg'].to_f) : record['door_rotation_y_deg'].to_f,
        'rot_z' => drawer ? record['drawer_rotation_z_deg'].to_f : (record.key?('door_rotation_z_deg') ? record['door_rotation_z_deg'].to_f : record['door_rotation_deg'].to_f)
      }

      profiles = record['placement_profiles']
      saved = profiles.is_a?(Hash) ? profiles[case_name.to_s] : nil
      return defaults unless saved.is_a?(Hash)

      result = defaults.dup
      href = saved['horizontal_reference'].to_s
      result['horizontal_reference'] = href if %w[auto left center right].include?(href)
      vref = (saved['vertical_reference'] || saved['reference']).to_s
      result['vertical_reference'] = vref if %w[top center bottom].include?(vref)

      result['horizontal_cm'] = saved['horizontal_cm'].to_f if saved.key?('horizontal_cm')
      result['vertical_cm'] = saved['vertical_cm'].to_f if saved.key?('vertical_cm')
      result['vertical_cm'] = saved['offset_cm'].to_f if saved.key?('offset_cm')
      %w[move_x_cm move_y_cm move_z_cm rot_x rot_y rot_z].each do |key|
        result[key] = saved[key].to_f if saved.key?(key)
      end
      result
    end

    def normal_handle_effective_unit_type_for_door(door_start_z)
      base_type = active_normal_handle_unit_type
      data = @active_design_data.is_a?(Hash) ? @active_design_data : {}
      return base_type unless data['normal_handle_high_door_rule'].to_s == 'yes'

      threshold_cm = data['normal_handle_high_door_threshold'].to_f
      threshold_cm = 150.0 if threshold_cm <= 0
      start_cm = door_start_z.to_f / 1.cm.to_f

      # القاعدة المطلوبة: أي ضلفة تبدأ عند/فوق الحد تتعامل كعلوية.
      start_cm >= threshold_cm ? 'upper' : base_type
    end

    def add_normal_handle_to_door(door_instance, direction, door_width, door_height, door_start_z = 0.0)
      record = active_normal_handle_record
      return nil unless record && door_instance && door_instance.valid?
      definition = custom_asset_definition(Sketchup.active_model, record['path'], record['name'])
      return nil unless definition

      effective_unit_type = direction.to_s == 'flip_up' ? 'flap' : normal_handle_effective_unit_type_for_door(door_start_z)
      case_settings = normal_handle_case_settings(record, effective_unit_type)

      href = case_settings['horizontal_reference'].to_s
      edge_mode = case href
                  when 'left' then :left
                  when 'right' then :right
                  when 'center' then nil
                  else direction.to_s == 'right' ? :left : :right
                  end
      edge = [case_settings['horizontal_cm'].to_f, 0].max.cm
      center_x = href == 'center' ? case_settings['horizontal_cm'].to_f.cm : 0.0

      vertical_mode = case_settings['vertical_reference'].to_s.to_sym
      vertical_mode = :center unless [:top, :bottom, :center].include?(vertical_mode)
      vertical = [case_settings['vertical_cm'].to_f, 0].max.cm
      center_z = vertical_mode == :center ? case_settings['vertical_cm'].to_f.cm : 0.0

      door_rx = case_settings['rot_x'].to_f
      door_ry = case_settings['rot_y'].to_f
      door_rz = case_settings['rot_z'].to_f

      mount_custom_handle_on_front(
        door_instance, definition, 'NORMAL_HANDLE', record['name'],
        edge_mode: edge_mode,
        edge_offset: edge,
        center_x_offset: center_x,
        vertical_mode: vertical_mode,
        vertical_offset: vertical,
        center_z_offset: center_z,
        rotation_x_deg: door_rx, rotation_y_deg: door_ry, rotation_z_deg: door_rz,
        move_x: case_settings['move_x_cm'].to_f.cm,
        move_y: case_settings['move_y_cm'].to_f.cm,
        move_z: case_settings['move_z_cm'].to_f.cm,
        rigid_follow: false,
        extra_attrs: {
          'PARENT_FRONT'=>'door',
          'HINGE_DIRECTION'=>direction.to_s,
          'UNIT_TYPE'=>effective_unit_type
        }
      )
    rescue => error
      puts "MHDESIGN normal door handle failed: #{error.class}: #{error.message}"
      raise error
    end

    def add_normal_handle_to_drawer_front(front_instance, front_width, front_height)
      record = active_normal_handle_record
      return nil unless record && front_instance && front_instance.valid?
      definition = custom_asset_definition(Sketchup.active_model, record['path'], record['name'])
      return nil unless definition

      drawer_case = normal_handle_case_settings(record, 'drawer')
      href = drawer_case['horizontal_reference'].to_s
      drawer_edge_mode = href == 'left' ? :left : (href == 'right' ? :right : nil)
      drawer_edge = [drawer_case['horizontal_cm'].to_f, 0].max.cm
      x_offset = href == 'center' ? drawer_case['horizontal_cm'].to_f.cm : 0.0

      drawer_ref = drawer_case['vertical_reference'].to_s.to_sym
      drawer_ref = :center unless [:top, :bottom, :center].include?(drawer_ref)
      drawer_offset = [drawer_case['vertical_cm'].to_f, 0].max.cm
      drawer_center_z = drawer_ref == :center ? drawer_case['vertical_cm'].to_f.cm : 0.0

      drawer_rx = drawer_case['rot_x'].to_f
      drawer_ry = drawer_case['rot_y'].to_f
      drawer_rz = drawer_case['rot_z'].to_f

      mount_custom_handle_on_front(
        front_instance, definition, 'NORMAL_HANDLE', record['name'],
        edge_mode: drawer_edge_mode,
        edge_offset: drawer_edge,
        vertical_mode: drawer_ref,
        vertical_offset: drawer_offset,
        center_x_offset: x_offset,
        center_z_offset: drawer_center_z,
        rotation_x_deg: drawer_rx, rotation_y_deg: drawer_ry, rotation_z_deg: drawer_rz,
        move_x: drawer_case['move_x_cm'].to_f.cm,
        move_y: drawer_case['move_y_cm'].to_f.cm,
        move_z: drawer_case['move_z_cm'].to_f.cm,
        rigid_follow: false,
        extra_attrs: {'PARENT_FRONT'=>'drawer_front'}
      )
    rescue => error
      puts "MHDESIGN normal drawer handle failed: #{error.class}: #{error.message}"
      raise error
    end

    def custom_interior_accessory_record(name)
      wanted = name.to_s.strip
      return nil if wanted.empty?
      custom_asset_catalogs['interior'].find { |item| item.is_a?(Hash) && item['name'].to_s.strip == wanted }
    end

    # يضع الإكسسوار داخل حدود الفتحة نفسها. أصل ملف SKP يعتبر نقطة البداية المحلية
    # للإكسسوار، ويتم ضبط عرضه فقط عند طلب ذلك مع الحفاظ على باقي أبعاده الأصلية.
    def add_custom_interior_accessory(entities, model, name, x, z, opening_width, opening_height, depth)
      record = custom_interior_accessory_record(name)
      return nil unless record
      definition = custom_asset_definition(model, record['path'], record['name'])
      return nil unless definition

      bbox = definition.bounds
      source_w = bbox.width.to_f
      mode = record['width_mode'].to_s
      clearance = [record['side_clearance'].to_f, 0].max.cm
      target_w = case mode
                 when 'fixed'
                   [record['fixed_width'].to_f, 0.1].max.cm
                 when 'clearance', 'opening_minus_sides'
                   [opening_width.to_f - clearance * 2.0, 0.1.cm].max
                 else
                   [opening_width.to_f, 0.1.cm].max
                 end
      scale_x = source_w > 0.001 ? target_w.to_f / source_w : 1.0
      placed_w = source_w * scale_x
      px = x.to_f + (opening_width.to_f - placed_w) / 2.0 - bbox.min.x.to_f * scale_x
      # /2 كود خاص: يوسّط جسم الإكسسوار نفسه، وليس الـOrigin.
      bottom_raw = record['bottom_offset'].to_s.strip
      depth_raw = record['depth_offset'].to_s.strip
      center_z = bottom_raw == '/2'
      center_y = depth_raw == '/2'
      pz = center_z ? z.to_f : (z.to_f + bottom_raw.to_f.cm - bbox.min.z.to_f)
      py = center_y ? 0.0 : (depth_raw.to_f.cm - bbox.min.y.to_f)

      # دوران حر للإكسسوار على X/Y/Z. قيم الصفر تحفظ اتجاه الموديل الأصلي.
      # rotation_z_deg القديم يظل مدعومًا تلقائيًا.
      rx = record['rotation_x_deg'].to_f.degrees
      ry = record['rotation_y_deg'].to_f.degrees
      rz = record['rotation_z_deg'].to_f.degrees

      tr = Geom::Transformation.translation([px, py, pz]) *
           Geom::Transformation.rotation(ORIGIN, Z_AXIS, rz) *
           Geom::Transformation.rotation(ORIGIN, Y_AXIS, ry) *
           Geom::Transformation.rotation(ORIGIN, X_AXIS, rx) *
           Geom::Transformation.scaling(scale_x, 1.0, 1.0)
      instance = entities.add_instance(definition, tr)

      # بعد الـScale والدوران نستخدم الـBoundingBox الحقيقي للإكسسوار،
      # وبذلك /2 يظل صحيحًا مهما كان Origin ملف SKP أو أبعاد/دوران العنصر.
      if center_z || center_y
        ib = instance.bounds
        dx2 = 0.0
        dy2 = center_y ? (depth.to_f / 2.0 - ib.center.y.to_f) : 0.0
        dz2 = center_z ? (z.to_f + opening_height.to_f / 2.0 - ib.center.z.to_f) : 0.0
        instance.transform!(Geom::Transformation.translation([dx2, dy2, dz2]))
      end
      stamp_custom_accessory(instance, record['name'], 'INTERIOR')
      instance.set_attribute('MHD_DRESSING', 'OPENING_ACCESSORY', true)
      instance.set_attribute('MHD_DRESSING', 'OPENING_WIDTH_CM', opening_width.to_f / 1.cm.to_f)
      instance.set_attribute('MHD_DRESSING', 'OPENING_HEIGHT_CM', opening_height.to_f / 1.cm.to_f)
      instance
    rescue => error
      puts "MHDESIGN interior accessory skipped: #{error.message}"
      nil
    end

    # إكسسوار سحاب: الإكسسوار + وش أمامي داخل Component واحد متحرك.
    # لا يوجد شاسيه درج داخلي. الضغط على الوش يشغل نفس حركة الدرج للأمام.
    def add_sliding_custom_interior_accessory(entities, model, name, x, z, opening_width, opening_height, depth,
                                               thickness, front_material, back_material, data,
                                               left_boundary = :outer, right_boundary = :outer,
                                               bottom_boundary = :outer, top_boundary = :outer)
      record = custom_interior_accessory_record(name)
      return nil unless record

      group = entities.add_group
      ge = group.entities

      # الإكسسوار نفسه محلي داخل مجموعة السحاب.
      accessory = add_custom_interior_accessory(ge, model, name, 0, 0, opening_width, opening_height, depth)
      raise "#{MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_1A29DACB1628')}#{name}»." unless accessory && accessory.valid?

      clearance = [data.is_a?(Hash) ? data['door_clearance'].to_f : 0.1, 0].max.cm
      left_overlay   = left_boundary.to_s   == 'outer' ? thickness.to_f : thickness.to_f / 2.0
      right_overlay  = right_boundary.to_s  == 'outer' ? thickness.to_f : thickness.to_f / 2.0
      bottom_overlay = bottom_boundary.to_s == 'outer' ? thickness.to_f : thickness.to_f / 2.0
      top_overlay    = top_boundary.to_s    == 'outer' ? thickness.to_f : thickness.to_f / 2.0

      front_x = -left_overlay + clearance
      front_z = -bottom_overlay + clearance
      front_w = opening_width.to_f + left_overlay + right_overlay - clearance * 2.0
      front_h = opening_height.to_f + bottom_overlay + top_overlay - clearance * 2.0
      raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_CECBF2EC6015') if front_w <= 0 || front_h <= 0

      front_thickness = 1.8.cm
      front_y = -front_thickness
      front_name = "وش سحاب إكسسوار #{name}"
      front = add_drawer_front(
        ge, model, front_name,
        front_x, front_y, front_z,
        front_w, front_thickness, front_h,
        front_material, back_material,
        true
      )
      raise "#{MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_7B9FB4ED02B2')}#{name}»." unless front && front.valid?

      # نحول المجموعة كلها إلى Component متحرك؛ هكذا الإكسسوار والوش يتحركان معًا.
      slider = group.to_component
      clean_name = qualified_part_name("سحاب إكسسوار #{name}")
      slider.definition.name = unique_name(model, clean_name)
      slider.name = clean_name
      slider.set_attribute('MHD_DRESSING', 'CUSTOM_SLIDING_ACCESSORY', true)
      slider.set_attribute('MHD_DRESSING', 'CUSTOM_ACCESSORY_NAME', name.to_s)
      slider.set_attribute('MHD_DRESSING', 'NO_DRAWER_CHASSIS', true)

      # موضع الغلق هو نفس إحداثيات الفتحة، والحركة للأمام بمقدار عمق الوحدة.
      slider.transform!(Geom::Transformation.translation([x.to_f, 0, z.to_f]))
      configure_dynamic_drawer(slider, front, 0.0, depth.to_f)
      slider
    rescue => error
      begin
        group.erase! if defined?(group) && group && group.valid?
      rescue
      end
      puts "MHDESIGN sliding accessory failed: #{error.class}: #{error.message}"
      raise error
    end

    def html_escape(value)
      value.to_s.gsub('&', '&amp;').gsub('"', '&quot;').gsub('<', '&lt;').gsub('>', '&gt;')
    end

    def html_dc_options(options)
      options.map do |option|
        value = html_escape(option['value'])
        label = html_escape(MHDESIGN::Language.for_tool('dressing_straight').t(option['label']))
        %(<option value="#{value}">#{label}</option>)
      end.join
    end

    def html(data)
      library_defaults = custom_asset_catalogs['library_settings135']
      data = data.merge(library_defaults) if !@current_wardrobe && library_defaults.is_a?(Hash)
      door_options = dc_list_options(@current_wardrobe, 'base_unit_1_f', [
        {'label'=>'HPL','value'=>'HPL'}, {'label'=>'POLYLACK','value'=>'POLYLACK'},
        {'label'=>'UVLACK','value'=>'UVLACK'}, {'label'=>'PVC','value'=>'PVC'},
        {'label'=>'MELAMIN','value'=>'MELAMIN'}
      ])
      carcass_options = dc_list_options(@current_wardrobe, 'base_unit_1_j', [
        {'label'=>'كونتر ابيض','value'=>'كونتر ابيض'},
        {'label'=>'كونتر خشابي','value'=>'كونتر خشابي'},
        {'label'=>'بنفس خامة الضلفة','value'=>'=BASE_UNIT_1!BASE_UNIT_1_f'}
      ])
      back_options = dc_list_options(@current_wardrobe, 'base_unit_1_h', [
        {'label'=>'ضهر ابيض','value'=>'ضهر ابيض'},
        {'label'=>'ضهر خشابي','value'=>'ضهر خشابي'},
        {'label'=>'ضهر ميلامين','value'=>'ضهر ميلامين'}
      ])
      door_material_options = html_dc_options(door_options)
      carcass_material_options = html_dc_options(carcass_options)
      back_material_options = html_dc_options(back_options)
      direct_material_options = (door_options + carcass_options).reject { |opt| opt['value'].to_s.strip.start_with?('=') }.uniq { |opt| opt['value'].to_s }
      side_override_material_options = html_dc_options([
        {'label'=>'نفس خامة الشاسيه','value'=>'__carcass__'},
        {'label'=>'نفس خامة الضلفة','value'=>'__door__'}
      ] + direct_material_options)
      visible_side_material_options = html_dc_options([{'label'=>'نفس خامة الضلفة','value'=>'__door__'}] + door_options.reject { |opt| opt['value'].to_s.strip.start_with?('=') })
      <<-HTML
