/* Industrial Dark workspace. The form and SVG keep their existing renderers. */
:root {
  --bg-app: #0B111A;
  --bg-header: #101B27;
  --bg-panel: #1A2633;
  --bg-elevated: #253443;
  --bg-input: #101923;
  --bg-preview: #101824;
  --accent: #08C9C3;
  --accent-bright: #27E5DC;
  --text-primary: #F4F7FA;
  --text-secondary: #A6B5C3;
  --border: #405467;
  --warning: #F2B72F;
  --panel-radius: 12px;
  --panel-shadow: 0 8px 24px #00000040;
  --active-glow: 0 0 12px #08C9C340;
  --transition: 160ms ease;
  --header-gradient: linear-gradient(110deg, #0A111A 0%, #142536 55%, #087F83 100%);
  --panel-gradient: linear-gradient(145deg, #293A4B 0%, #1A2633 45%, #111B27 100%);
  --preview-gradient: radial-gradient(ellipse at 50% 42%, #354454 0%, #1B2734 48%, #0B121D 100%);
  --action-gradient: linear-gradient(90deg, #08BDB8 0%, #13DDD2 55%, #05B9B5 100%);
}
body {
  background: var(--bg-app);
  color: var(--text-primary);
  font-family: Cairo, Tajawal, "Segoe UI", Tahoma, Arial, sans-serif;
  font-size: 13px;
  line-height: 1.45;
}
button, input, select, textarea { font: inherit; }
.head {
  flex: 0 0 66px;
  height: auto;
  padding: 8px 18px;
  background: var(--header-gradient);
  border-color: var(--border);
}
.logo { width: 46px; height: 46px; border-color: #ffffff40; background: #101b2780; }
.title { font-size: 20px; font-weight: 750; }
.sub { margin-top: 1px; color: #c8dbe5; }
.main {
  display: grid;
  grid-template-columns: minmax(322px, 375px) minmax(0, 1fr);
  grid-template-rows: minmax(0, 1fr);
  gap: 12px;
  padding: 12px;
  overflow: hidden;
}
.panel {
  display: flex;
  flex-direction: column;
  width: auto;
  min-width: 0;
  background: var(--panel-gradient);
  border: 1px solid var(--border);
  border-radius: var(--panel-radius);
  box-shadow: var(--panel-shadow);
}
.panel-title {
  flex: 0 0 auto;
  height: auto;
  min-height: 45px;
  padding: 9px 12px;
  background: var(--bg-header);
  border-bottom: 1px solid var(--border);
  color: var(--text-primary);
  font-size: 14px;
  font-weight: 750;
}
.preview .panel-title button { flex: 0 0 auto; }
.editor {
  flex: 1;
  height: auto;
  min-height: 0;
  overflow: auto;
  overscroll-behavior: contain;
  scroll-padding-top: 60px;
  padding: 0 12px 16px;
}
.option-tabs {
  top: 0;
  margin: 0 -12px 11px;
  padding: 8px 10px;
  background: var(--bg-panel);
  border-color: var(--border);
  grid-template-columns: repeat(4, minmax(0, 1fr));
}
.option-tab {
  min-width: 0;
  height: auto;
  min-height: 38px;
  padding: 3px 2px;
  line-height: 1.2;
  font-size: 11px;
  color: var(--text-secondary);
  background: var(--bg-input);
  border-color: var(--border);
}
.option-tab.active, .preset.active, .template-card.active, .bay.active {
  background: #08c9c322;
  color: var(--text-primary);
  border-color: var(--accent-bright);
  box-shadow: inset 0 0 0 1px #08c9c32a;
}
.section { border-color: var(--border); }
.section-title { color: var(--text-primary); font-size: 13px; }
.structure-group, .rule-card, .selection-card {
  background: #182430;
  border-color: var(--border);
  border-radius: 9px;
}
.structure-group summary {
  padding: 8px 10px;
  background: var(--bg-elevated);
  color: var(--text-primary);
  font-weight: 720;
}
.structure-group summary:before { color: var(--accent-bright); margin-inline-end: 6px; margin-left: 0; }
.structure-group-body { padding: 9px 10px; }
.grid2 { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 7px 9px; }
.field { min-width: 0; margin-bottom: 6px; }
.field label { color: var(--text-secondary); line-height: 1.3; font-weight: 650; }
.field input:not([type="range"]), .field select, .bay input {
  height: 39px;
  min-width: 0;
  color: var(--text-primary);
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: 7px;
  padding: 0 8px;
}
.field select { padding-inline-end: 22px; }
input[type="number"] { direction: ltr; text-align: right; font-variant-numeric: tabular-nums; }
input[type="range"] { direction: ltr; accent-color: var(--accent); cursor: pointer; }
select option { color: var(--text-primary); background: var(--bg-input); }
button, .field input, .field select, summary {
  transition: background-color var(--transition), border-color var(--transition), box-shadow var(--transition), filter var(--transition);
}
button:not(:disabled):hover { filter: brightness(1.13); }
summary:hover { background-color: #304255; }
button:focus-visible, summary:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible {
  outline: 2px solid var(--accent-bright);
  outline-offset: 2px;
}
.structure-group summary:focus-visible { outline-offset: -3px; }
.field input:focus, .field select:focus { border-color: var(--accent-bright); box-shadow: none; }
button:disabled, .field input:disabled, .field select:disabled { opacity: .5; cursor: not-allowed; }
.add { background: #15323b; border: 1px solid #398087; color: var(--text-primary); }
.selection-card { border-inline-start: 3px solid var(--accent); }
.selection-name { color: var(--accent-bright); }
.editor #heightLockStatus162:not(:empty) { display: block !important; color: var(--text-secondary); }
#heightLockButton162[aria-pressed="true"] { color: var(--warning); border-color: #ad832e; background: #352d23; }
.canvas-wrap { flex: 1; height: auto; min-height: 0; padding: 10px; }
.canvas {
  display: block;
  flex: 1;
  min-height: 0;
  background: var(--bg-preview);
  background-image: var(--preview-gradient);
  border-color: var(--border);
  border-radius: 8px;
  font-variant-numeric: tabular-nums;
}
.canvas [onclick] { cursor: pointer; }
.canvas [onclick]:focus-visible { outline: 2px solid var(--accent-bright); outline-offset: 2px; }
.canvas [data-mhd-locked="true"] { fill: var(--warning); }
.part-hit:hover { filter: brightness(1.15); }
.part-selected { stroke: var(--accent-bright) !important; }
.foot {
  flex: 0 0 auto;
  height: auto;
  min-height: 60px;
  gap: 10px;
  padding: 9px 12px;
  background: var(--bg-header);
  border-color: var(--border);
}
.create, .rules-save { background: var(--action-gradient); color: #091a21; font-weight: 800; }
.create:hover, .rules-save:hover { background: var(--action-gradient); }
.create:focus-visible { box-shadow: var(--active-glow); }
.cancel, .rules-cancel { background: #26313e; color: var(--text-primary); border-color: var(--border); }
.rules-modal { border-radius: var(--panel-radius); border-color: var(--border); background: var(--bg-panel); }
.rules-head { background: var(--bg-header); border-color: var(--border); }
.error-head { background: #412628; }
.error-head .rules-title { color: #ffcdc4; }
.edit-rules { background: var(--warning); color: #22180a; }
.edit-rules:hover { background: var(--warning); }
.rules-title { font-weight: 750; }
.creation-progress-bar { background: var(--action-gradient); }
::-webkit-scrollbar { width: 9px; height: 9px; }
::-webkit-scrollbar-thumb { background: #506477; border: 2px solid #1a2633; }
html[dir="ltr"] .panel, html[dir="ltr"] .rules-modal { direction: ltr; }
html[dir="ltr"] input[type="number"] { text-align: left; }
@media (max-width: 710px) {
  .main { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto; overflow: auto; }
  .options { height: 55vh; min-height: 265px; }
  .preview { height: 65vh; min-height: 315px; }
  .head { flex-basis: 56px; }
  .title { font-size: 17px; }
  .logo { width: 38px; height: 38px; }
}
@media (prefers-reduced-motion: reduce) {
  button, summary, .field input, .field select, .creation-progress-bar { transition: none; }
}


/* Workspace shell: the identity and tabs are separate from the scrolling form. */
.app { display: grid; grid-template-rows: auto minmax(0,1fr) auto; }
.head {
  position: relative;
  isolation: isolate;
  display: grid;
  grid-template-columns: minmax(0,1fr) auto minmax(0,1fr);
  align-items: center;
  direction: ltr;
  min-height: clamp(66px, 6.35vw, 100px);
  padding: 9px clamp(12px, 3.25vw, 49px);
  overflow: hidden;
  background: var(--header-gradient);
}
.workspace-brand { display: flex; min-width: 0; align-items: center; gap: 12px; font-weight: 800; font-size: clamp(12px,1.6vw,23px); letter-spacing: .025em; }
.head .title { position: relative; direction: rtl; font-size: clamp(20px,2.1vw,33px); line-height: 1.25; white-space: nowrap; }
.head .sub { color: var(--text-primary); font-size: clamp(10px,1.2vw,16px); margin-top: 5px; }
.head .title-icon { vertical-align: -.15em; margin-inline-end: .4em; color: var(--accent-bright); }
.head-art { position: absolute; inset: 0 0 0 auto; z-index: -1; width: min(35%,500px); pointer-events: none;
  background: linear-gradient(145deg,transparent 42%,#006e6840 42%,#07c9c382 49%,transparent 52%,transparent 72%,#079d9630 72%); }
.head-art svg { position: absolute; right: 5%; bottom: -12px; width: 118px; height: 110px; color: #36c9c2; opacity: .58; }
.main { grid-template-columns: clamp(296px,28vw,425px) minmax(0,1fr); gap: clamp(8px,1.05vw,16px); padding: 12px; }






.workspace-icon { width: 17px; height: 17px; flex: 0 0 auto; }
.panel { border-radius: 12px; }
.panel-title { min-height: 43px; padding: 7px 12px; background: var(--bg-elevated); }
.options-title { display: flex; align-items: center; gap: 8px; font-size: clamp(14px,1.35vw,20px); }
.options-title .workspace-icon { color: var(--accent-bright); }

.unit-identity { padding-top: 10px; margin-bottom: 8px; }
.unit-identity .field { margin: 0; }
.unit-identity .global-settings-button { margin-top: 7px; border-color: var(--border); background: #1b303b; }
.options .option-tabs { position: sticky; top: 0; z-index: 20; margin: 0 -10px 10px; padding: 7px 10px; border-bottom: 1px solid var(--border); gap: 5px; }
.option-tab { min-height: clamp(43px,4.5vw,65px); padding: 4px 2px; font-size: clamp(10px,.88vw,13px); background: var(--bg-elevated); }
.option-tab .workspace-icon { display: block; width: 16px; height: 16px; margin: 0 auto 3px; }
.option-tab.active { background: #123a42; }
.options .editor { padding: 0 10px 16px; scroll-padding-top: 80px; }
.field label { overflow-wrap: anywhere; }
.field input:not([type="range"]), .field select, .bay input { height: clamp(34px,2.65vw,40px); }
.preview .panel-title { display: flex; align-items: center; gap: 8px; }
.preview .preview-instruction { flex: 1; min-width: 0; }
.preview .panel-title .workspace-icon { color: var(--accent-bright); }
.preview-action, .viewport-tool { display: inline-flex; align-items: center; justify-content: center; gap: 5px; border: 1px solid var(--border); border-radius: 7px; background: #14212c; color: var(--text-primary); cursor: pointer; }
.preview-action { min-height: 29px; padding: 3px 9px; border-color: var(--accent); white-space: nowrap; font-weight: 750; }
.canvas-wrap {
  position: relative;
  isolation: isolate;
  display: grid;
  flex: 1;
  grid-template-columns: auto minmax(0,1fr);
  grid-template-rows: minmax(0,1fr) auto;
  column-gap: 8px;
  min-height: 0;
  padding: 8px;
  direction: ltr;
  background: var(--preview-gradient);
  overflow: hidden;
}
.canvas-wrap::before { content: ''; position: absolute; z-index: -1; inset: auto 0 0; height: 23%; pointer-events: none;
  background: linear-gradient(0deg,#0b121ddd,transparent), radial-gradient(ellipse at 52% 32%,#7b90b267,transparent 72%); }
.viewport-tools { grid-row: 1; align-self: center; display: flex; flex-direction: column; gap: 5px; padding: 4px; border: 1px solid var(--border); border-radius: 9px; background: #101923e0; box-shadow: 0 6px 14px #0005; }
.viewport-tool { width: clamp(27px,2.5vw,38px); height: clamp(27px,2.5vw,38px); }
.viewport-tool:hover { border-color: var(--accent); }
.viewport-tool:focus-visible { outline-offset: -2px; }
.canvas { grid-column: 2; grid-row: 1; width: 100%; height: 100%; background: none; border: 0; overflow: hidden; }
.canvas > text[data-workspace-summary] { display: none; }
.canvas .shelf, .canvas .rod { stroke-linecap: round; }
.preview-info { grid-column: 2; grid-row: 2; justify-self: center; display: flex; align-items: center; gap: 7px; max-width: 100%; padding: 4px 11px; border: 1px solid var(--border); border-radius: 9px; background: #101923e8; color: var(--text-primary); font-size: clamp(10px,1.04vw,15px); font-weight: 700; }
.preview-info[hidden] { display: none; }
.preview-info .workspace-icon { color: var(--accent-bright); }
.preview-info span { overflow-wrap: anywhere; }
.foot { min-height: clamp(53px,6vw,86px); padding: clamp(7px,1.1vw,15px) 12px; }
.foot .create, .foot .cancel { display: inline-flex; align-items: center; justify-content: center; gap: 7px; min-height: 38px; }
.foot .create { flex: 3.2; font-size: clamp(14px,1.4vw,21px); }
.foot .cancel { flex: 1; }
@media (max-width: 850px) and (min-width: 711px) {
  .main { grid-template-columns: minmax(260px,290px) minmax(0,1fr); padding: 8px; }
  .preview .panel-title { flex-wrap: wrap; }
  .preview .preview-instruction { flex-basis: calc(100% - 28px); }
}
