<div id="wallReliefModal" class="modal-overlay"><div class="rules-modal" style="max-width:760px"><div class="rules-head"><div class="rules-title">#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_386E99CE6B6C')}</div><button class="rules-close" onclick="closeWallRelief()">×</button></div><div class="rules-body"><div class="grid2"><div class="field"><label>#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_FB9F6A251269')}</label><input id="reliefWallWidth" type="number" min="20" step="0.1"></div><div class="field"><label>#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_E917C20C8DDF')}</label><select id="reliefPlacement"><option value="right">#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_CA080C4F66E8')}</option><option value="left">#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_F8FD489B7E0C')}</option></select></div><div class="field"><label>#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_8A1D2223C36B')}</label><input id="reliefCabinetOffset" type="number" min="0" step="0.1" value="0"></div><div class="field"><label>#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_390AB2AE341E')}</label><input id="reliefCabinetWidth" type="text" disabled></div><div class="field"><label>#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_8705C6EABF1E')}</label><input id="reliefColumnCount" type="number" min="0" max="8" step="1"></div></div><div class="rules-note" style="margin-bottom:8px">#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_44169765A4E2')}</div><div id="reliefRows"></div><div style="margin-top:8px;border:1px solid #405467;border-radius:8px;background:#0c1421;padding:8px"><svg id="reliefCanvas" viewBox="0 0 700 180" style="width:100%;height:180px"></svg></div><div class="rules-note" style="margin-top:8px">#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_7EF45308B8CF')}</div></div><div class="rules-foot"><button class="rules-cancel" onclick="removeWallRelief()">#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_98492B373FE2')}</button><button class="rules-save" onclick="saveWallRelief()">#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_3C206D2BC2B0')}</button></div></div></div>
<script>
const INITIAL=#{JSON.generate(data)};const GLOBAL_CATALOG=#{JSON.generate(custom_asset_catalogs)};const PRESETS={shelves:['#{MHDESIGN::Language.for_tool('dressing_straight').js_fragment('TEXT_743AFF1CDA13')}','☰'],hanging:['#{MHDESIGN::Language.for_tool('dressing_straight').js_fragment('TEXT_6C4ECDB08805')}','⌒'],double_hang:['#{MHDESIGN::Language.for_tool('dressing_straight').js_fragment('TEXT_34FD688FE6A0')}','⌒⌒'],drawers:['#{MHDESIGN::Language.for_tool('dressing_straight').js_fragment('TEXT_086A51C8AB70')}','▤'],drawers_hang:['#{MHDESIGN::Language.for_tool('dressing_straight').js_fragment('TEXT_1A11B3F23BD8')}','▤⌒'],split_mix:['#{MHDESIGN::Language.for_tool('dressing_straight').js_fragment('TEXT_39EE428CC457')}','▥']};let bays=INITIAL.bays,selected=0,easyTemplate=String(INITIAL.easy_template||'1'),advancedMode=false,layoutTree=null,selectedPath=[],selectionTarget='opening',selectedPart=null,activeOptionsTab='structure',cabinetWidth=Number(INITIAL.width||120);const $=id=>document.getElementById(id);const val=id=>parseFloat($(id).value||0);
let butterflySupportRules=Array.isArray(INITIAL.butterfly_support_rules)&&INITIAL.butterfly_support_rules.length?INITIAL.butterfly_support_rules.map(r=>({threshold:Number(r.threshold)||65,count:Math.max(1,Math.min(3,parseInt(r.count||1)))})):[{threshold:65,count:1}];
function renderButterflySupportRules(){const box=$('butterflySupportRules');if(!box)return;box.innerHTML='';butterflySupportRules.forEach((r,i)=>{const row=document.createElement('div');row.className='grid2';row.style.marginBottom='6px';row.innerHTML=`<div class="field"><label>#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_E261843EAFEC')}</label><input type="number" min="1" step="1" value="${r.threshold}" onchange="butterflySupportRules[${i}].threshold=Math.max(1,Number(this.value)||1)"></div><div class="field"><label>#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_C33635725C1F')}</label><div style="display:flex;gap:6px;align-items:center"><select onchange="butterflySupportRules[${i}].count=parseInt(this.value)"><option value="1"${r.count===1?' selected':''}>1</option><option value="2"${r.count===2?' selected':''}>2</option><option value="3"${r.count===3?' selected':''}>3</option></select>${i>0?`<button type="button" class="small-btn" onclick="removeButterflySupportRule(${i})">#{MHDESIGN::Language.for_tool('dressing_straight').html('COMMON_DELETE')}</button>`:''}</div></div>`;box.appendChild(row)})}
function addButterflySupportRule(){const last=butterflySupportRules[butterflySupportRules.length-1]||{threshold:65};butterflySupportRules.push({threshold:Math.max(1,Number(last.threshold)||65)+50,count:1});renderButterflySupportRules()}
function removeButterflySupportRule(i){if(i<=0)return;butterflySupportRules.splice(i,1);renderButterflySupportRules()}
let elitaSupportRules=Array.isArray(INITIAL.elita_support_rules)&&INITIAL.elita_support_rules.length?INITIAL.elita_support_rules.map(r=>({threshold:Number(r.threshold)||65,count:Math.max(1,Math.min(3,parseInt(r.count||1)))})):[{threshold:65,count:1}];
function renderElitaSupportRules(){const box=$('elitaSupportRules');if(!box)return;box.innerHTML='';elitaSupportRules.forEach((r,i)=>{const row=document.createElement('div');row.className='grid2';row.style.marginBottom='6px';row.innerHTML=`<div class="field"><label>#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_E261843EAFEC')}</label><input type="number" min="1" step="1" value="${r.threshold}" onchange="elitaSupportRules[${i}].threshold=Math.max(1,Number(this.value)||1)"></div><div class="field"><label>#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_02E78C7AC9D1')}</label><div style="display:flex;gap:6px;align-items:center"><select onchange="elitaSupportRules[${i}].count=parseInt(this.value)"><option value="1"${r.count===1?' selected':''}>1</option><option value="2"${r.count===2?' selected':''}>2</option><option value="3"${r.count===3?' selected':''}>3</option></select>${i>0?`<button type="button" class="small-btn" onclick="removeElitaSupportRule(${i})">#{MHDESIGN::Language.for_tool('dressing_straight').html('COMMON_DELETE')}</button>`:''}</div></div>`;box.appendChild(row)})}
function addElitaSupportRule(){const last=elitaSupportRules[elitaSupportRules.length-1]||{threshold:65};elitaSupportRules.push({threshold:Math.max(1,Number(last.threshold)||65)+50,count:1});renderElitaSupportRules()}
function removeElitaSupportRule(i){if(i<=0)return;elitaSupportRules.splice(i,1);renderElitaSupportRules()}
let topCorniceJoineryRules=Array.isArray(INITIAL.top_cornice_joinery_rules)&&INITIAL.top_cornice_joinery_rules.length?INITIAL.top_cornice_joinery_rules.map(r=>({threshold:Number(r.threshold)||65,count:Math.max(1,Math.min(3,parseInt(r.count||1)))})):[{threshold:65,count:1}];
let woodPlinthJoineryRules=Array.isArray(INITIAL.wood_plinth_joinery_rules)&&INITIAL.wood_plinth_joinery_rules.length?INITIAL.wood_plinth_joinery_rules.map(r=>({threshold:Number(r.threshold)||65,count:Math.max(1,Math.min(3,parseInt(r.count||1)))})):[{threshold:65,count:1}];
function trimRuleState(kind){return kind==='cornice'?topCorniceJoineryRules:woodPlinthJoineryRules}
function trimRuleBox(kind){return $(kind==='cornice'?'topCorniceJoineryRules':'woodPlinthJoineryRules')}
function renderTrimRules(kind){const arr=trimRuleState(kind),box=trimRuleBox(kind);if(!box)return;box.innerHTML='';arr.forEach((r,i)=>{const row=document.createElement('div');row.className='grid2';row.style.marginBottom='6px';row.innerHTML=`<div class="field"><label>#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_E261843EAFEC')}</label><input type="number" min="1" step="1" value="${r.threshold}" onchange="trimRuleState('${kind}')[${i}].threshold=Math.max(1,Number(this.value)||1)"></div><div class="field"><label>#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_0AD4F6EE7E16')}</label><div style="display:flex;gap:6px"><select onchange="trimRuleState('${kind}')[${i}].count=parseInt(this.value)"><option value="1"${r.count===1?' selected':''}>1</option><option value="2"${r.count===2?' selected':''}>2</option><option value="3"${r.count===3?' selected':''}>3</option></select>${i>0?`<button type="button" class="small-btn" onclick="removeTrimRule('${kind}',${i})">#{MHDESIGN::Language.for_tool('dressing_straight').html('COMMON_DELETE')}</button>`:''}</div></div>`;box.appendChild(row)})}
function addTrimRule(kind){const arr=trimRuleState(kind),last=arr[arr.length-1]||{threshold:65};arr.push({threshold:Math.max(1,Number(last.threshold)||65)+50,count:1});renderTrimRules(kind)}
function removeTrimRule(kind,i){if(i<=0)return;trimRuleState(kind).splice(i,1);renderTrimRules(kind)}
function updateTrimJoineryOptions(){const c=$('topCorniceJoinery').value,p=$('woodPlinthJoinery').value;$('topCorniceJoineryOptions').style.display=(c==='butterfly')?'':'none';$('woodPlinthJoineryOptions').style.display=(p==='butterfly')?'':'none'}
let wallRelief=INITIAL.wall_relief||{enabled:'no',wall_width:cabinetWidth,placement:'left',cabinet_offset:0,columns:[]};if(!Array.isArray(wallRelief.columns))wallRelief.columns=[];else wallRelief.columns=wallRelief.columns.filter(c=>c&&typeof c==='object');
function reliefWallWidth(){return Math.max(cabinetWidth,Number(wallRelief.wall_width||cabinetWidth))}
function reliefCabinetStart(){const w=reliefWallWidth(),off=Math.max(0,Number(wallRelief.cabinet_offset||0)),side=wallRelief.placement==='right'?'right':'left';return side==='right'?Math.max(0,w-off-cabinetWidth):Math.min(off,Math.max(0,w-cabinetWidth))}
function reliefColumnLeft(c){const w=reliefWallWidth(),cw=Math.max(0,Number(c.width||0));if(c&&c.distance!==undefined){const d=Math.max(0,Number(c.distance||0));return c.side==='right'?w-d-cw:d}return Number(c.left||0)}
function activeReliefs(){if(wallRelief.enabled!=='yes')return[];const start=reliefCabinetStart();return (wallRelief.columns||[]).map((c,i)=>{const left=reliefColumnLeft(c);return{index:i,x0:Math.max(0,left-start),x1:Math.min(cabinetWidth,left+Number(c.width)-start),depth:Number(c.depth),strategy:c.mode||'depth_avoid'}}).filter(r=>r.x1>r.x0&&r.depth>0)}
function cabinetBayRegions(n,x,w,t,out=[]){if(n&&n.dir==='v'&&n.external&&Array.isArray(n.children)&&n.children.length>1){const ratio=splitRatio162(n,.08,.92),w1=(w-t)*ratio;cabinetBayRegions(n.children[0],x,w1,t,out);cabinetBayRegions(n.children[1],x+w1+t,w-w1-t,t,out)}else out.push({x0:x,x1:x+w});return out}
function suggestedReliefs(){const physical=activeReliefs(),t=Math.max(.1,val('thickness')),bays=layoutTree?cabinetBayRegions(layoutTree,t,Math.max(1,cabinetWidth-2*t),t,[]):[];return physical.flatMap(r=>{if(r.strategy==='true_notch')return[Object.assign({},r,{x0:Math.max(0,r.x0-t),x1:Math.min(cabinetWidth,r.x1+t),depth:r.depth+t,mode:'cladded_partition'})];let hit=bays.filter(b=>r.x1>b.x0+.1&&r.x0<b.x1-.1);if(!hit.length&&bays.length)hit=[bays.reduce((a,b)=>Math.abs((a.x0+a.x1-r.x0-r.x1)/2)<Math.abs((b.x0+b.x1-r.x0-r.x1)/2)?a:b)];return hit.map(b=>Object.assign({},r,{x0:b.x0,x1:b.x1,mode:'bay_depth'}))})}
function renderReliefRows(){const count=Math.max(0,Math.min(8,parseInt($('reliefColumnCount').value||0))),old=wallRelief.columns||[];$('reliefRows').innerHTML=Array.from({length:count},(_,i)=>{const c=old[i]||{side:'right',distance:100+i*100,width:60,depth:20,mode:'depth_avoid'},side=c.side==='right'?'right':'left',distance=c.distance!==undefined?Number(c.distance):Number(c.left||0);return`<div class="rule-card"><h3>#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_09F5E0AB38F5')} ${i+1}</h3><div class="grid2"><div class="field"><label>#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_799147E4B5CF')}</label><select class="relief-side"><option value="right" ${side==='right'?'selected':''}>#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_CA080C4F66E8')}</option><option value="left" ${side==='left'?'selected':''}>#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_F8FD489B7E0C')}</option></select></div><div class="field"><label>#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_F8EEF71A321A')}</label><input class="relief-distance" type="number" min="0" step="0.1" value="${distance}"></div><div class="field"><label>#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_93869CBB3875')}</label><input class="relief-width" type="number" min="1" step="0.1" value="${Number(c.width)}"></div><div class="field"><label>#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_B9D76CD00093')}</label><input class="relief-depth" type="number" min="0.1" step="0.1" value="${Number(c.depth)}"></div><div class="field"><label>#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_8AABCE842221')}</label><select class="relief-mode"><option value="depth_avoid" ${(c.mode||'depth_avoid')==='depth_avoid'?'selected':''}>#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_A54865455FFC')}</option><option value="true_notch" ${c.mode==='true_notch'?'selected':''}>#{MHDESIGN::Language.for_tool('dressing_straight').html('TEXT_4A482880A827')}</option></select></div></div></div>`}).join('');$('reliefRows').querySelectorAll('input,select').forEach(el=>el.addEventListener(el.tagName==='SELECT'?'change':'input',previewWallRelief));previewWallRelief()}
