 ['interior','handles','drawer_accessories'].forEach(kind=>{
  const personal=(GLOBAL_CATALOG[kind]||[]).filter(record=>record&&!record.library_managed);
  if(saved)personal.forEach(record=>{
   if(!record.library_copy)return;
   const persisted=(saved[kind]||[]).find(item=>libraryAssetName184(item)===libraryAssetName184(record));
   if(persisted){record.path=persisted.path;delete record.library_copy;}
  });
  const excluded=new Set(personal.map(libraryAssetName184).concat(hiddenLibraryAssets184(kind)));
  GLOBAL_CATALOG[kind]=personal.concat((managed[kind]||[]).filter(record=>!excluded.has(libraryAssetName184(record))));
 });
 if(edited){
