<script>
(function enhanceIndustrialWorkspace() {
  const canvas = document.getElementById('canvas');
  const heightLock = document.getElementById('heightLockButton162');
  const rtl = document.documentElement.dir === 'rtl';
  const actionSelector = 'g[onclick], text[onclick], rect[onclick], line[onclick], path[onclick], polygon[onclick]';
  const labels = {
    opening: rtl ? 'تحديد الفراغ' : 'Select opening',
    column: rtl ? 'تحديد العمود' : 'Select column',
    part: rtl ? 'تحديد القطعة' : 'Select part',
    side: rtl ? 'تحديد الجنب الظاهر' : 'Select visible side',
    lock: rtl ? 'قفل الارتفاع' : 'Lock height',
    unlock: rtl ? 'فتح قفل الارتفاع' : 'Unlock height'
  };

  document.querySelectorAll('.field').forEach(field => {
    const label = field.querySelector('label');
    const controls = field.querySelectorAll('input[id]:not([type="hidden"]),select[id],textarea[id]');
    if (label && !label.htmlFor && controls.length === 1) label.htmlFor = controls[0].id;
  });

  function decoratePreview() {
    const seen = new Set();
    canvas.querySelectorAll(actionSelector).forEach(target => {
      const action = target.getAttribute('onclick');
      // The wide, transparent shelf hit area shares the line's existing action.
      if (target.getAttribute('stroke') === 'transparent' || seen.has(action)) return;
      let label;
      if (action.indexOf('selectLayout(') === 0) {
        const texts = target.querySelectorAll('text:not([onclick])');
        const name = texts.length ? texts[texts.length - 1].textContent.trim() : '';
        label = name ? labels.opening + ' – ' + name : labels.opening;
      } else if (action.indexOf('selectColumn(') === 0) {
        label = target.textContent.trim() || labels.column;
      } else if (action.indexOf('selectPart(') === 0) {
        const parts = action.split("'");
        label = parts[5] || labels.part;
      } else if (action.indexOf('selectVisibleSide(') === 0) {
        label = labels.side + ' – ' + (action.indexOf("'left'") >= 0 ? (rtl ? 'شمال' : 'Left') : (rtl ? 'يمين' : 'Right'));
      } else if (action.indexOf('toggleHeightAt162(') === 0) {
        const locked = target.textContent.trim() === '🔒';
        target.setAttribute('data-mhd-locked', String(locked));
        target.setAttribute('aria-pressed', String(locked));
        label = locked ? labels.unlock : labels.lock;
      }
      if (!label) return;
      seen.add(action);
      target.setAttribute('tabindex', '0');
      target.setAttribute('role', 'button');
      target.setAttribute('aria-label', label);
    });
  }

  function updateLockState() {
    if (heightLock) heightLock.setAttribute('aria-pressed', String(heightLock.textContent.indexOf('🔒') >= 0));
  }

  canvas.addEventListener('keydown', event => {
    const target = event.target;
    if ((event.key !== 'Enter' && event.key !== ' ') || !target.matches('[role="button"][onclick]')) return;
    event.preventDefault();
    if (event.repeat) return;
    const action = target.getAttribute('onclick');
    target.dispatchEvent(new MouseEvent('click', {bubbles: true, cancelable: true, view: window}));
    if (!canvas.contains(target)) {
      decoratePreview();
      const replacement = Array.from(canvas.querySelectorAll('[tabindex="0"][onclick]'))
        .find(item => item.getAttribute('onclick') === action);
      if (replacement) replacement.focus();
    }
  });

  decoratePreview();
  updateLockState();
  new MutationObserver(decoratePreview).observe(canvas, {childList: true, subtree: true});
  if (heightLock) new MutationObserver(updateLockState).observe(heightLock, {childList: true, characterData: true, subtree: true});
}());

</script><script>
(function wireCadViewport() {
  const canvas = document.getElementById('canvas');
  const caption = document.getElementById('workspacePreviewInfo178');
  const captionText = caption.querySelector('span');
  const zoomIn = document.getElementById('workspaceZoomIn178');
  const zoomOut = document.getElementById('workspaceZoomOut178');
  const fit = document.getElementById('workspaceFit178');
  let zoom = 1;
  let scheduled = false;

  function updateView() {
    scheduled = false;
    const hasDrawing = canvas.childElementCount > 0;
    const summary = canvas.querySelector('[data-workspace-summary]');
    caption.hidden = !hasDrawing;
    if (hasDrawing) {
      captionText.textContent = (summary || document.getElementById('previewTitle')).textContent.trim();
      const bounds = canvas.getBBox();
      if (bounds.width > 0 && bounds.height > 0) {
        const padding = 17;
        const width = (bounds.width + padding * 2) / zoom;
        const height = (bounds.height + padding * 2) / zoom;
        const x = bounds.x + (bounds.width - width) / 2;
        const y = bounds.y + (bounds.height - height) / 2;
        canvas.setAttribute('viewBox', [x, y, width, height].join(' '));
      }
    } else {
      canvas.setAttribute('viewBox', '0 0 760 520');
    }
    zoomIn.disabled = !hasDrawing || zoom >= 1.75;
    zoomOut.disabled = !hasDrawing || zoom <= 0.65;
    fit.disabled = !hasDrawing;
  }

  function scheduleView() {
    if (!scheduled) {
      scheduled = true;
      requestAnimationFrame(updateView);
    }
  }
  zoomIn.addEventListener('click', () => { zoom = Math.min(1.75, zoom * 1.2); scheduleView(); });
  zoomOut.addEventListener('click', () => { zoom = Math.max(0.65, zoom / 1.2); scheduleView(); });
  fit.addEventListener('click', () => { zoom = 1; scheduleView(); });
  new MutationObserver(scheduleView).observe(canvas, {childList: true});
  scheduleView();
}());

