    end

    def show_dialog(preferred_unit = nil)
      if @dialog
        @dialog.bring_to_front rescue nil
        start_dressing_library_sync if @dressing_library_dialog_ready
        return true
      end
      restore_motion_links(Sketchup.active_model)
      @current_wardrobe = selected_wardrobe(preferred_unit)
      unless @current_wardrobe
        UI.messagebox(MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_E2DDEE9A1F25'))
        return false
      end
      sign_straight_wardrobe!(@current_wardrobe)
      @current_wardrobe.make_unique
      # make_unique ينشئ Definition جديدًا؛ نعيد تثبيت التوقيع على النسخة الجديدة.
      sign_straight_wardrobe!(@current_wardrobe)
      # make_unique ينسخ الـAttributes لكن ينشئ Entities جديدة،
      # لذلك نعيد ربط الـObservers بالنسخة الجديدة فورًا.
      restore_motion_links(Sketchup.active_model)
      data = wardrobe_data(@current_wardrobe)
      @dialog = UI::HtmlDialog.new(dialog_title: MHDESIGN::Language.for_tool('dressing_straight').t(TITLE), preferences_key: PREF_KEY, scrollable: false, resizable: true, width: 1100, height: 760, style: UI::HtmlDialog::STYLE_DIALOG)
      @dialog.set_html(html(data))
      @dialog.add_action_callback('cancel') { @dialog.close if @dialog }
      @dialog.add_action_callback('open_doors') { open_doors }
      @dialog.add_action_callback('close_doors') { close_doors }
      @dialog.add_action_callback('choose_custom_asset_file') do |_context, _kind|
        begin
          info = import_custom_skp_file(_kind)
          @dialog.execute_script("window.mhdCustomAssetFileChosen(#{JSON.generate(info)})") if info && @dialog
        rescue => error
          @dialog.execute_script("showToolError('تعذر إضافة الملف', #{JSON.generate(error.message.to_s)})") if @dialog
        end
      end
      @dialog.add_action_callback('save_custom_asset_catalog') do |_context, payload|
        begin
          saved = save_custom_asset_catalogs(JSON.parse(payload.to_s))
          managed = dressing_library_managed_catalog
          @dialog.execute_script("window.applyManagedDressingLibrary183(#{JSON.generate(managed)}, #{JSON.generate(saved)})") if @dialog
          @dialog.execute_script("window.mhdCustomAssetCatalogSaved && window.mhdCustomAssetCatalogSaved()") if @dialog
        rescue => error
          puts "MHDESIGN save custom asset catalog failed: #{error.class}: #{error.message}"
          @dialog.execute_script("showToolError('تعذر حفظ مكتبة الإكسسوارات', #{JSON.generate(error.message.to_s)})") if @dialog
        end
      end
      @dialog.add_action_callback('export_custom_asset_library') do |_context, payload|
        begin
          snapshot = payload.to_s.empty? ? nil : JSON.parse(payload.to_s)
          path = export_custom_asset_package(snapshot)
          UI.messagebox("تم تصدير المكتبة بنجاح:\n#{path}") if path
        rescue => error
          UI.messagebox("تعذر تصدير المكتبة:\n#{error.message}")
        end
      end

      @dialog.add_action_callback('import_custom_asset_library') do |_context|
        begin
          result = import_custom_asset_package
          if result
            @dialog.execute_script("applyFullLibrary135(#{JSON.generate(result)})") if @dialog
            @custom_asset_definitions = {}
            UI.messagebox(MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_8FE6AEFE803F'))
          end
        rescue => error
          UI.messagebox("تعذر استيراد المكتبة:\n#{error.message}")
        end
      end

      @dialog.add_action_callback('create_dressing') do |_context, payload|
        begin
          data = JSON.parse(payload)
          root = create_dressing(data)
          update_creation_progress(100, 'تم إنشاء الدولاب بنجاح')
          @dialog.close if @dialog
        rescue => error
          if error.is_a?(BoardLimitError) && @dialog
            @dialog.execute_script("hideCreationLoading();showBoardErrors(#{JSON.generate(error.violations)})")
          elsif @dialog
            @dialog.execute_script("hideCreationLoading();showToolError('تعذر إنشاء الدولاب', #{JSON.generate(error.message.to_s)})")
          else
            UI.messagebox("تعذر إنشاء الدولاب:\n#{error.message}")
          end
        end
      end
      @dressing_library_dialog_ready = false
      @dialog.add_action_callback('dressing_library_ui_ready189') do |_context|
        next if @dressing_library_dialog_ready
        @dressing_library_dialog_ready = true
        start_dressing_library_sync
        catalog = dressing_library_managed_catalog
        @dialog.execute_script("window.applyManagedDressingLibrary183(#{JSON.generate(catalog)})") if @dialog
        update_dressing_library_status(@dressing_library_status) if @dressing_library_status
      end
      @dialog.set_on_closed do
        @dressing_library_dialog_ready = false
        close_doors
        @dialog = nil
        @current_wardrobe = nil
      end
      @dialog.show
      true
    end

    # مداخل واضحة لللانشر؛ كلها تحترم توقيع نوع الوحدة.
    def open_for_selection(unit = nil)
      show_dialog(unit)
    end

    def open_for_component(unit = nil)
      show_dialog(unit)
    end

    def open_for_unit(unit = nil)
      show_dialog(unit)
    end

    def door_entities
      return [] unless @current_wardrobe && @current_wardrobe.valid?
      @current_wardrobe.definition.entities.grep(Sketchup::ComponentInstance).select do |item|
        generated = item.get_attribute('MHD_DRESSING', 'GENERATED_COLUMN_DOOR')
        direction = item.get_attribute('MHD_DRESSING', 'HINGE_DIRECTION', '').to_s
        legacy_name = [item.name, MHDESIGN::Language.original_definition_name(item.definition),
                       item.get_attribute('dynamic_attributes', '_name'),
                       item.definition.get_attribute('dynamic_attributes', '_name')].join(' ')
        (generated || !direction.empty? || legacy_name.include?('ضلف')) && !item.hidden?
      end
    end

    def open_doors
      @door_transforms ||= {}
      door_entities.each do |door|
        next if @door_transforms.key?(door.persistent_id)
        @door_transforms[door.persistent_id] = door.transformation
        direction = door.get_attribute('MHD_DRESSING', 'HINGE_DIRECTION', '').to_s
        right = direction == 'right' || (direction.empty? && [door.name, MHDESIGN::Language.original_definition_name(door.definition)].join(' ').include?('يمين'))
        hinge_x = right ? @current_wardrobe.definition.bounds.max.x : @current_wardrobe.definition.bounds.min.x
        pivot = Geom::Point3d.new(hinge_x, door.bounds.min.y, door.bounds.min.z)
        angle = right ? -95.degrees : 95.degrees
        door.transform!(Geom::Transformation.rotation(pivot, Z_AXIS, angle))

        # Step 59: حرّك المقبض/الإكسسوار المرتبط فورًا في نفس لحظة فتح الضلفة.
        # الـEntityObserver في SketchUp يعمل بعد تغيير الضلفة (Timer 0)، وده كان بيخلي
        # المقبض يظهر كأنه مستني الضلفة تفتح ثم يلحق بها. المزامنة المباشرة هنا
        # تلغي التأخير، بينما يظل الـObserver موجودًا للحركة الخارجية/DC.
        sync_hinge_accessories(door)
      end
      Sketchup.active_model.active_view.invalidate
    end

    def close_doors
      return unless @door_transforms
      door_entities.each do |door|
        original = @door_transforms[door.persistent_id]
        if original
          door.transformation = original
          # نفس الفكرة عند القفل: يرجع المقبض في نفس لحظة رجوع الضلفة.
          sync_hinge_accessories(door)
        end
      end
      @door_transforms = nil
      Sketchup.active_model.active_view.invalidate
    rescue
      @door_transforms = nil
    end


    # ============================================================
    # MHD STRAIGHT PERFORMANCE PROFILER
    # تشخيص فقط — لا يغيّر أي هندسة أو نجارة أو تخريم.
    # يطبع زمن الإنشاء الكلي وأهم مراحل المستقيم في Ruby Console.
    # ============================================================
    STRAIGHT_PERF_LABEL = '10.53.33 STRAIGHT DETACHED PERF'.freeze unless const_defined?(:STRAIGHT_PERF_LABEL)

    def perf_now
      Process.clock_gettime(Process::CLOCK_MONOTONIC)
    rescue
      Time.now.to_f
    end

    def perf_reset!
      @perf_stats = {}
      @perf_active = true
      @perf_create_started_at = perf_now
      root = @current_wardrobe
      if root && root.valid?
        tr = root.transformation
        origin = tr.origin
        puts
        puts "================ MHD STRAIGHT PERF #{STRAIGHT_PERF_LABEL} ================"
        puts format("[MHD ROOT] origin=(%.3f, %.3f, %.3f) in", origin.x.to_f, origin.y.to_f, origin.z.to_f)
        puts format("[MHD ROOT] xaxis_len=%.6f yaxis_len=%.6f zaxis_len=%.6f",
                    tr.xaxis.length.to_f, tr.yaxis.length.to_f, tr.zaxis.length.to_f)
      else
        puts
        puts "================ MHD STRAIGHT PERF #{STRAIGHT_PERF_LABEL} ================"
      end
    rescue
      @perf_stats = {}
      @perf_active = true
      @perf_create_started_at = Time.now.to_f
    end

    def perf_measure(label)
      return yield unless @perf_active
      started = perf_now
      begin
        yield
      ensure
        elapsed = perf_now - started
        @perf_stats ||= {}
        row = (@perf_stats[label.to_s] ||= {'total'=>0.0, 'calls'=>0, 'max'=>0.0})
        row['total'] += elapsed
        row['calls'] += 1
        row['max'] = elapsed if elapsed > row['max']
      end
    end

    def perf_report!
      total = perf_now - @perf_create_started_at.to_f
      stats = (@perf_stats || {}).sort_by { |_name, row| -row['total'].to_f }
      puts format("[MHD PERF] %-32s %10.3f s", 'TOTAL_CREATE', total)
      stats.each do |name, row|
        puts format("[MHD PERF] %-32s %10.3f s   calls=%-4d max=%8.3f s",
                    name, row['total'].to_f, row['calls'].to_i, row['max'].to_f)
      end
      puts "============================================================"
      puts
    rescue => error
      puts "[MHD PERF] report error: #{error.message}"
    ensure
      @perf_active = false
    end

    # Wardrobe-only interception layer. All kitchen implementations remain
    # byte-for-byte in the base module and are reached through super.
    module WardrobeGola128
      WG_MISSING_DIVIDER = 'لا يمكن تنفيذ مقبض جولا رأسي في منتصف الدولاب بدون قاطع طولي. برجاء إضافة قاطع طولي أولًا.'.freeze
      WG_KEYS = %w[handle_type gola_unit_type handle_cut_height handle_reveal_body
        handle_reveal_inset handle_reveal_height handle_wood_material_source
        gola_divider_position gola_sharing_mode].freeze

      def wg_enabled?(data = @active_design_data)
        data.is_a?(Hash) && data['handle_type'].to_s == 'gola_reveal' && data['gola_unit_type'].to_s == 'wardrobe'
      end

      def wg_direction(data = @active_design_data)
        value = data['wardrobe_gola_direction'] || data['gola_wardrobe_orientation']
        %w[horizontal vertical].include?(value.to_s) ? value.to_s : 'horizontal'
      end

      def wg_normalize!(data)
        value = data['wardrobe_gola_direction'] || data['gola_wardrobe_orientation']
        # Read the old global key first. Only migrate a legacy per-front value
        # when all explicit values agree; never pick one arbitrary door.
        legacy_direction_bug = data['version'].to_s.start_with?('10.54.39-') && value.to_s == 'horizontal'
        if (value.nil? || legacy_direction_bug) && data['layout_tree'].is_a?(Hash)
          values = []
          walk = lambda do |n|
            next unless n.is_a?(Hash)
            %w[column_door opening_door].each do |key|
              h = n[key].is_a?(Hash) ? n[key]['handle_override'] : nil
              next unless h.is_a?(Hash)
              v = h['wardrobe_gola_direction'] || h['gola_wardrobe_orientation']
              values << v if %w[horizontal vertical].include?(v)
            end
            Array(n['children']).each { |c| walk.call(c) }
          end
          walk.call(data['layout_tree'])
          values.uniq!
          value = values.first if values.length == 1
        end
        data['wardrobe_gola_direction'] = %w[horizontal vertical].include?(value) ? value : 'horizontal'
        data['wardrobe_gola_vertical_extent'] = 'full' unless %w[full between notch_top notch_base].include?(data['wardrobe_gola_vertical_extent'].to_s)
        data
      end

      def wardrobe_data(item)
        wg_normalize!(super)
      end

      def wg_global_front_cut160(data)
        return data unless wg_enabled?(data) && wg_direction(data) == 'vertical'
        data.merge('shelf_front_cut'=>[data['shelf_front_cut'].to_f,data['handle_reveal_inset'].to_f,0.0].max,
          'cut_full_partitions'=>'yes')
      end

      def create_dressing(data)
        wg_normalize!(data)
        data = wg_global_front_cut160(data)
        @wg_plan = nil
        if wg_enabled?(data) && !data['layout_tree'].is_a?(Hash)
          raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_3C286D19838A')
        end
        super
      ensure
        @wg_plan = nil
        @wg_building_handle = false
      end

      def active_front_handle_value(key, fallback = nil)
        return @active_design_data.fetch(key, fallback) if wg_enabled? && WG_KEYS.include?(key)
        super
      end

      def door_handle_adjusted_front_height(height, requested_cut = nil)
        return height.to_f if wg_enabled?
        super
      end

      def collect_leaf_regions(*args)
        return @wg_virtual_regions if @wg_virtual_tree && args[0].equal?(@wg_virtual_tree)
        super
      end

      def prepare_internal_gola_reveal_zones(tree, x, z, width, height, t, data)
        return super unless wg_enabled?(data)
        @wg_plan = wg_prepare_plan(tree,x,z,width,height,t,data)
        @gola_reveal_zones = [] # kitchen zones cannot create implicit end Ls
      end

      def wg_collect_fronts(tree,x,z,width,height,t,data)
        leaves = collect_leaf_regions(tree,x,z,width,height,t)
        records = leaves.filter_map do |r|
          d = r['node']['opening_door']
          next unless d.is_a?(Hash) && d['enabled'].to_s == 'yes'
          left = r['left'] == :outer ? t : t/2.0
          right = r['right'] == :outer ? t : t/2.0
          bottom = r['bottom'] == :outer || !adjacent_horizontal_front_face?(r,leaves,:bottom,t) ? t : t/2.0
          top = r['top'] == :outer || !adjacent_horizontal_front_face?(r,leaves,:top,t) ? t : t/2.0
          r.merge('kind'=>'opening','config'=>d,'id'=>"opening:#{r['path'].join('.')}",
            'cx0'=>r['x']-left,'cx1'=>r['x']+r['width']+right,
            'cz0'=>r['z']-bottom,'cz1'=>r['z']+r['height']+top)
        end
        columns = collect_column_regions(tree,x,width,t)
        c = [data['door_clearance'].to_f,0].max.cm
        columns.each_with_index do |r,i|
          d = r['node']['column_door']
          next unless d.is_a?(Hash) && d['enabled'].to_s == 'yes'
          drawer_top = overlay_drawer_top(r['node'],z,height,t)
          base_bottom = drawer_top ? drawer_top+t/2.0+c : c
          span = opening_door_free_span(r['node'],r['x'],z,r['width'],height,t,base_bottom,data['height'].to_f.cm-c,c)
          raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_962BE6195EF9') unless span
          # free_span contains finished FRONT edges with half-overlay and
          # clearance. Recover the structural opening edges before matching a
          # column door to an opening door across a horizontal divider.
          raw_bottom = (span[0]-c).abs <= 0.01.cm ? z.to_f : span[0]+t/2.0-c
          cabinet_top = data['height'].to_f.cm
          raw_top = (span[1]-(cabinet_top-c)).abs <= 0.01.cm ? cabinet_top-t : span[1]-t/2.0+c
          records << r.merge('kind'=>'column','config'=>d,'id'=>"column:#{r['path'].join('.')}",
            'z'=>raw_bottom,'height'=>raw_top-raw_bottom,
            'cx0'=>r['x']-(i.zero? ? t : t/2.0),
            'cx1'=>r['x']+r['width']+(i==columns.length-1 ? t : t/2.0),
            'cz0'=>span[0]-c,'cz1'=>span[1]+c)
        end
        records.each do |r|
          r['direction'] = r['config']['direction'].to_s
          r['direction'] = 'right' if r['direction'].empty?
          r['direction'] = r['config']['filler_side'] if %w[left right].include?(r['config']['filler_side'].to_s)
          raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_FC0B963F44DF') unless %w[left right double].include?(r['direction'])
        end
        records
      end

      def wg_collect_dividers(n,x,z,w,h,t,result=[],filler=false)
        return result unless n.is_a?(Hash)
        d = n['column_door']
        filler ||= d.is_a?(Hash) && %w[left right].include?(d['filler_side'].to_s)
        children = Array(n['children'])
        return result unless children.length >= 2 && %w[h v].include?(n['dir'].to_s)
        ratio = layout_split_ratio162(n)
        if n['dir'] == 'v'
          omitted = filler && children.any? { |c| subtree_has_thick_drawers?(c) }
          space = omitted ? 0.0 : t
          first = (w-space)*ratio
          result << {'x'=>x+first,'z0'=>z,'z1'=>z+h,'width'=>t} unless omitted
          wg_collect_dividers(children[0],x,z,first,h,t,result,filler)
          wg_collect_dividers(children[1],x+first+space,z,w-first-space,h,t,result,filler)
        else
          top = (h-t)*ratio; bottom = h-t-top
          wg_collect_dividers(children[0],x,z+bottom+t,w,top,t,result,filler)
          wg_collect_dividers(children[1],x,z,w,bottom,t,result,filler)
        end
        result
      end

      # Ask the unchanged upper-unit engine for one real door boundary. This
      # tiny virtual tree contains two front regions, not the cabinet's shelves.
      def wg_upper_zone(upper,lower,x0,x1,t,data)
        settings = data.select { |key,_| WG_KEYS.include?(key) }.merge('gola_unit_type'=>'upper')
        leaf = lambda { {'type'=>'empty','opening_door'=>{'enabled'=>'yes','direction'=>'right','handle_override'=>settings.dup}} }
        top_h = upper['height'].to_f; bottom_h = lower['height'].to_f
        virtual = {'dir'=>'h','ratio'=>top_h/(top_h+bottom_h),'children'=>[leaf.call,leaf.call]}
        previous_data = @active_design_data; previous_override = @active_front_handle_override; previous_zones = @gola_reveal_zones
        begin
          @wg_virtual_tree = virtual
          @wg_virtual_regions = [
            {'node'=>virtual['children'][0],'x'=>x0,'width'=>x1-x0,'z'=>upper['z'].to_f,'height'=>top_h,'path'=>[0]},
            {'node'=>virtual['children'][1],'x'=>x0,'width'=>x1-x0,'z'=>lower['z'].to_f,'height'=>bottom_h,'path'=>[1]}]
          @active_design_data = data.merge('gola_unit_type'=>'upper','layout_tree'=>virtual)
          @active_front_handle_override = nil
          zones = DressingDesigner.instance_method(:prepare_internal_gola_reveal_zones).bind(self).call(
            virtual,x0,lower['z'].to_f,x1-x0,top_h+bottom_h+t,t,@active_design_data)
          zone = zones.find { |v| v['source'] == 'opening_divider_positioned' }
          raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_E18133B5CC02') unless zone
          zone.dup
        ensure
          @active_design_data = previous_data; @active_front_handle_override = previous_override; @gola_reveal_zones = previous_zones
          @wg_virtual_tree = nil; @wg_virtual_regions = nil
        end
      end

      def wg_prepare_plan(tree,x,z,width,height,t,data)
        fronts = wg_collect_fronts(tree,x,z,width,height,t,data)
        raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_4F5B00EE1DD0') if fronts.empty?
        raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_2AD161D8BA16') unless data['door_system'].to_s == 'hinged'
        inset = data['handle_reveal_inset'].to_f.cm
        reveal = data['handle_reveal_height'].to_f.cm
        raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_335E10F1C6F7') unless inset > 0.01.cm && inset < data['depth'].to_f.cm-t
        raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_41ECF793297B') unless reveal > 0.1.cm
        body = data['handle_reveal_body'].to_s == 'wood' ? 'wood' : 'metal'
        plan = {'fronts'=>fronts,'runs'=>[],'cuts'=>[],'t'=>t,'inset'=>inset,'reveal'=>reveal,
          'body'=>body,'direction'=>wg_direction(data),'total'=>width+2*t,
          'front_cut'=>[data['handle_cut_height'].to_f,0].max.cm}
        if plan['direction'] == 'horizontal'
          fronts.each do |upper|
            fronts.each do |lower|
              next if upper.equal?(lower)
              next unless (upper['z'].to_f-(lower['z'].to_f+lower['height'].to_f+t)).abs <= 0.15.cm
              ox0 = [upper['x'].to_f,lower['x'].to_f].max
              ox1 = [upper['x'].to_f+upper['width'].to_f,lower['x'].to_f+lower['width'].to_f].min
              next unless ox1-ox0 > 0.15.cm
              zone = wg_upper_zone(upper,lower,ox0,ox1,t,data)
              zone.merge!('x0'=>[upper['cx0'],lower['cx0']].max,'x1'=>[upper['cx1'],lower['cx1']].min,
                'members'=>[[upper['id'],'upper'],[lower['id'],'lower']],
                'divider_bottom'=>lower['z'].to_f+lower['height'].to_f,'divider_top'=>upper['z'].to_f)
              plan['runs'] << zone
            end
          end
          raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_031120779D1B') if plan['runs'].empty?
          merged = []
          plan['runs'].sort_by { |r| [r['z0'],r['x0']] }.each do |run|
            last = merged.last
            if last && (last['z0']-run['z0']).abs < 0.1.cm && (last['z1']-run['z1']).abs < 0.1.cm && (last['x0']-run['x0']).abs < 0.05.cm && (last['x1']-run['x1']).abs < 0.05.cm
              last['x1'] = [last['x1'],run['x1']].max
              last['members'] = (last['members']+run['members']).uniq
            else
              merged << run.dup
            end
          end
          plan['runs'] = merged
        else
          expanded = fronts.flat_map do |r|
            if r['direction'] == 'double'
              mid = (r['cx0']+r['cx1'])/2.0
              [r.merge('cx1'=>mid,'direction'=>'left'),r.merge('cx0'=>mid,'direction'=>'right')]
            else
              [r]
            end
          end
          columns = []
          expanded.sort_by { |r| r['cx0'] }.each do |r|
            col = columns.find { |c| (c[0]['cx0']-r['cx0']).abs < 0.2.cm && (c[0]['cx1']-r['cx1']).abs < 0.2.cm }
            col ? col << r : columns << [r]
          end
          raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_2BC9BDEF90D0') unless [1,2].include?(columns.length)
          z0 = fronts.map { |r| r['cz0'] }.min
          z1 = fronts.map { |r| r['cz1'] }.max
          if columns.length == 1
            dirs = columns[0].map { |r| r['direction'] }.uniq
            raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_C582577EF38A') unless dirs.length == 1
            side = dirs[0] == 'right' ? 'left' : 'right'
            raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_F50C0062D319') if glass_side?(data,side)
            x0 = side == 'left' ? 0.0 : plan['total']-reveal
            plan['runs'] << {'x0'=>x0,'x1'=>x0+reveal,'z0'=>z0,'z1'=>z1,'profile'=>'L','side'=>side,'members'=>fronts.map { |f| [f['id'],'edge'] }}
          else
            columns.sort_by! { |c| c[0]['cx0'] }
            left_end = columns[0][0]['cx1']; right_start = columns[1][0]['cx0']
            raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_B109DD53A0C2') if (left_end-right_start).abs > 0.2.cm
            center = (left_end+right_start)/2.0
            dividers = wg_collect_dividers(tree,x,z,width,height,t)
            support = dividers.find { |d| (d['x']+t/2.0-center).abs < 0.15.cm && d['z0'] <= z0+t+0.15.cm && d['z1'] >= z1-t-0.15.cm }
            raise WG_MISSING_DIVIDER unless support
            unless columns[0].all? { |f| f['direction'] == 'left' } && columns[1].all? { |f| f['direction'] == 'right' }
              raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_5B69F0B59757')
            end
            plan['runs'] << {'x0'=>center-reveal/2.0,'x1'=>center+reveal/2.0,'z0'=>z0,'z1'=>z1,
              'profile'=>'C','center'=>center,'support_x'=>support['x'],
              'members'=>columns[0].map { |f| [f['id'],'left'] }+columns[1].map { |f| [f['id'],'right'] }}
          end
        end
        if plan['direction'] == 'vertical'
          extent = data['wardrobe_gola_vertical_extent'].to_s
          plan['runs'].each do |run|
            case extent
            when 'between'
              run['z0'] = [run['z0'],t].max
              run['z1'] = [run['z1'],data['height'].to_f.cm-t].min
            when 'notch_top'
              run['z0'] = t
              run['z1'] = data['height'].to_f.cm
            when 'notch_base'
              run['z0'] = 0.0
              run['z1'] = data['height'].to_f.cm-t
            end
            raise 'لا يوجد ارتفاع كافٍ للجولا في طريقة التركيب المختارة.' if run['z1']-run['z0'] <= 0.1.cm
          end
        end
        plan['runs'].each do |run|
          profile = run['profile'] == 'C' ? 'C' : 'L'
          minimum = body == 'wood' ? (profile == 'C' ? 2*t : t)+0.1.cm : 0.4.cm
          raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_89CB98C4DA6D') if reveal <= minimum || (body == 'wood' && inset <= t+0.05.cm)
          plan['cuts'] << {'x0'=>run['x0'],'x1'=>run['x1'],'z0'=>run['z0'],'z1'=>run['z1'],'depth'=>inset}
        end
        plan
      end

      def build_straight_grooved_shell(entities,model,total,depth,height,t,material,data)
        return super unless wg_enabled?
        # Suppress the old kitchen automatic top reveal, without changing DATA_JSON.
        super(entities,model,total,depth,height,t,material,data.merge('handle_type'=>'normal'))
      end

      def add_vertical_panel_with_gola_profile(*args)
        return nil if wg_enabled?
        super
      end

      # Shelf/partition front setbacks are resolved by the existing global-cut
      # pipeline; the compatibility hook no longer changes individual pieces.
      def wg_auto_front_setback151(x,y,z,w,d,h,badges)
        [y,d]
      end

      def wg_carve_part(part,x,y,z,w,d,h,badges)
        return part unless wg_enabled? && @wg_plan && !@wg_building_handle && part && part.valid?
        tags = Array(badges).map(&:to_s)
        return part unless (tags & %w[MAIN_CARCASS PARTITION BAY_INTERNAL_PARTITION SHELF DRAWER_CHASSIS]).any?
        return part if (tags & %w[DOOR_PANEL DRAWER_FRONT DRAWER_BOX HARDWARE ACCESSORY KITCHEN_GOLA_WOOD_HANDLE]).any?
        return part if part.get_attribute('MHD_DRESSING','WARDROBE_GOLA_CARVED_V128',false)
        @wg_plan['cuts'].each do |cut|
          x0 = [x.to_f,cut['x0']].max; x1 = [x.to_f+w.to_f,cut['x1']].min
          z0 = [z.to_f,cut['z0']].max; z1 = [z.to_f+h.to_f,cut['z1']].min
          amount = cut['depth']-y.to_f
          next if x1-x0 <= 0.01.cm || z1-z0 <= 0.01.cm || amount <= 0.01.cm
          raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_F5C0302BF04A') if amount >= d.to_f-0.1.cm
          inverse = part.transformation.inverse
          points = [[x0,y,z0],[x1,y,z0],[x1,y,z1],[x0,y,z1]].map { |v| Geom::Point3d.new(*v).transform(inverse) }
          inward = Geom::Vector3d.new(0,1,0).transform(inverse)
          face = part.definition.entities.add_face(points)
          raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_13CD699E1C90') unless face
          face.reverse! if face.normal.dot(inward) > 0
          face.pushpull(-amount)
          part.set_attribute('MHD_DRESSING','WARDROBE_GOLA_INSET_CM',cut['depth']/1.cm.to_f)
        end
        part.set_attribute('MHD_DRESSING','WARDROBE_GOLA_CARVED_V128',true)
        part
      end

      def add_box(parent,model,name,x,y,z,w,d,h,material,badges=[])
        y,d = wg_auto_front_setback151(x,y,z,w,d,h,badges)
        wg_carve_part(super(parent,model,name,x,y,z,w,d,h,material,badges),x,y,z,w,d,h,badges)
      end

      def add_vertical_panel(parent,model,name,x,y,z,w,d,h,material,badges=[],side=nil)
        y,d = wg_auto_front_setback151(x,y,z,w,d,h,badges)
        wg_carve_part(super(parent,model,name,x,y,z,w,d,h,material,badges,side),x,y,z,w,d,h,badges)
      end

      def add_horizontal_grooved_panel(parent,model,name,x,y,z,w,d,h,material,badges=[],face_side=:top)
        y,d = wg_auto_front_setback151(x,y,z,w,d,h,badges)
        wg_carve_part(super(parent,model,name,x,y,z,w,d,h,material,badges,face_side),x,y,z,w,d,h,badges)
      end

      def add_full_side_with_plinth_rear_notch(parent,model,name,x,y,z,w,d,h,material,badges,rear_inset,notch_height,side)
        wg_carve_part(super,x,y,z,w,d,h,badges)
      end

      def wg_front_dimensions(hinge_x,z,width,height,direction,path)
        return [hinge_x,z,width,height] unless wg_enabled? && @wg_plan
        # Both column and opening doors use COLUMN_PATH; their physical span
        # disambiguates a shared path without rewriting existing attributes.
        candidates = @wg_plan['fronts'].select { |f| f['path'].join('.') == path.to_s }
        front = candidates.min_by { |f| (f['cz0']-z).abs+(f['cz1']-(z+height)).abs }
        return [hinge_x,z,width,height] unless front
        x0 = direction.to_s == 'right' ? hinge_x-width : hinge_x
        x1 = x0+width; top = z+height
        c = [@active_design_data['door_clearance'].to_f,0].max.cm
        @wg_plan['runs'].each do |run|
          roles = run['members'].select { |id,_| id == front['id'] }.map(&:last)
          next if roles.empty?
          if @wg_plan['direction'] == 'vertical'
            gap = @wg_plan['front_cut']
            if run['profile'] == 'C'
              center = run['center']
              if direction.to_s == 'left' && x1 <= center+0.2.cm
                x1 = [x1,center-gap/2.0].min
              elsif direction.to_s == 'right' && x0 >= center-0.2.cm
                x0 = [x0,center+gap/2.0].max
              end
            elsif run['side'] == 'left'
              x0 = [x0,gap+c].max
            else
              x1 = [x1,@wg_plan['total']-gap-c].min
            end
          else
            gap = run['handle_cut_height'].to_f
            center = (run['z0']+run['z1'])/2.0
            shared = run['sharing'] == 'shared'
            if roles.include?('upper')
              z = if shared
                    center+gap/2.0
                  elsif run['divider_position'] == 'below'
                    run['divider_bottom']+c-gap
                  else
                    # The base builder sees opening doors only when deciding
                    # half-overlay. A neighbouring column door must use the
                    # same structural divider center, not that incomplete base.
                    (run['divider_bottom']+run['divider_top'])/2.0+c+gap
                  end
            end
            if roles.include?('lower')
              top = if shared
                      center-gap/2.0
                    elsif run['divider_position'] == 'below'
                      run['z0']+(@wg_plan['body'] == 'wood' ? @wg_plan['t'] : 0.0)-c
                    else
                      run['divider_top']-c
                    end
            end
          end
        end
        raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_1D19B9913141') if x1-x0 <= 0.5.cm || top-z <= 0.5.cm
        [direction.to_s == 'right' ? x1 : x0,z,x1-x0,top-z]
      end

      def copy_dynamic_door(root,source,name,x,z,w,h,direction,style,path)
        x,z,w,h = wg_front_dimensions(x,z,w,h,direction,path)
        super(root,source,name,x,z,w,h,direction,style,path)
      end

      def copy_dynamic_glass_door(root,source,name,x,z,w,h,direction,path)
        x,z,w,h = wg_front_dimensions(x,z,w,h,direction,path)
        super(root,source,name,x,z,w,h,direction,path)
      end

      def build_wood_gola_handles(entities,model,total,depth,height,t,carcass,door,data)
        return super unless wg_enabled?(data)
        return [] unless @wg_plan && @wg_plan['body'] == 'wood'
        wg_build_handles(entities,model,carcass,door,data)
      end

      def build_metal_gola_handles(entities,model,total,depth,height,t,data)
        return super unless wg_enabled?(data)
        return [] unless @wg_plan && @wg_plan['body'] == 'metal'
        wg_build_handles(entities,model,nil,nil,data)
      end

      # Resolve the existing finish from the SAME L/C assets used by kitchens.
      # Do not invent a material name or create a replacement material.
      def wg_metal_material(model, profile = 'L')
        definitions = profile.to_s == 'C' ?
          [biltin_handle_c_definition(model),biltin_handle_definition(model)] :
          [biltin_handle_definition(model),biltin_handle_c_definition(model)]
        definitions.each do |definition|
          scores = Hash.new(0.0)
          visit = lambda do |entities, inherited, ancestry, depth|
            next if depth > 20
            entities.each do |entity|
              painted = entity.respond_to?(:material) ? entity.material : nil
              if entity.is_a?(Sketchup::Face)
                finish = painted || inherited || entity.back_material
                scores[finish] += [entity.area.to_f.abs,0.000001].max if finish
              elsif entity.respond_to?(:entities)
                visit.call(entity.entities,painted || inherited,ancestry,depth+1)
              elsif entity.respond_to?(:definition)
                nested = entity.definition
                next if ancestry.include?(nested.object_id)
                visit.call(nested.entities,painted || inherited,ancestry+[nested.object_id],depth+1)
              end
            end
          end
          visit.call(definition.entities,nil,[definition.object_id],0)
          winner = scores.max_by { |_material,area| area }
          return winner[0] if winner
        end
        raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_98B3349FF04E')
      end

      def wg_build_handles(entities,model,carcass,door,data)
        @wg_building_handle = true
        @wg_plan['runs'].map.with_index do |run,i|
          vertical = @wg_plan['direction'] == 'vertical'
          length = vertical ? run['z1']-run['z0'] : run['x1']-run['x0']
          reveal = @wg_plan['reveal']; inset = @wg_plan['inset']
          shape = run['profile'] == 'C' ? 'C' : 'L'
          right_wing = vertical ? run['side'] == 'right' : run['profile'] == 'L_UPPER_FLIP'
          group = entities.add_group
          group.name = "مقبض جولا دولاب #{vertical ? 'رأسي' : 'أفقي'} #{shape} #{i+1}"
          if @wg_plan['body'] == 'wood'
            material = data['handle_wood_material_source'].to_s == 'door' ? door : carcass
            material ||= carcass || door
            raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_F9019BBCE63B') unless material
            t = @wg_plan['t']
            add = lambda do |label,x,y,w,d|
              add_box_without_wall_relief(group.entities,model,"#{group.name} #{label} #{PART_SUFFIX}",x,y,0,w,d,length,material,
                ['KITCHEN_GOLA_WOOD_HANDLE','JOINERY_PART','WARDROBE_GOLA'])
            end
            old_pattern = @edge_band_pattern
            begin
              @edge_band_pattern = 'all_around'
              add.call('ضهر',0,inset-t,reveal,t)
              add.call('جناح شمال',0,0,t,inset-t) if shape == 'C' || !right_wing
              add.call('جناح يمين',reveal-t,0,t,inset-t) if shape == 'C' || right_wing
            ensure
              @edge_band_pattern = old_pattern
            end
          else
            # Constant aluminium wall thickness; an actual extruded section.
            # No non-uniform transverse scaling of downloaded SKP geometry.
            wall = 0.18.cm
            raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_9AD1659B5A58') unless inset > 2*wall && reveal > 2*wall
            points = if shape == 'C'
              [[0,0],[wall,0],[wall,inset-wall],[reveal-wall,inset-wall],[reveal-wall,0],[reveal,0],[reveal,inset],[0,inset]]
            elsif right_wing
              [[0,inset-wall],[reveal-wall,inset-wall],[reveal-wall,0],[reveal,0],[reveal,inset],[0,inset]]
            else
              [[0,0],[wall,0],[wall,inset-wall],[reveal,inset-wall],[reveal,inset],[0,inset]]
            end
            metal = wg_metal_material(model,shape)
            item = add_xy_profile(group.entities,model,"#{group.name} معدن",points,0,0,0,reveal,inset,length,metal,['HARDWARE','ACCESSORY','WARDROBE_GOLA'])
            item.set_attribute('MHD_DRESSING','GOLA_PROFILE',shape)
            item.set_attribute('MHD_DRESSING','GOLA_METAL_WALL_CM',0.18)
          end
          transform = if vertical
            Geom::Transformation.translation([run['x0'],0,run['z0']])
          else
            Geom::Transformation.axes(Geom::Point3d.new(run['x0'],0,run['z0']),
              Geom::Vector3d.new(0,0,1),Geom::Vector3d.new(0,1,0),Geom::Vector3d.new(1,0,0))
          end
          # Flip Along Red (local X) about the section center; keep the same physical bounds.
          if vertical
            transform = transform * Geom::Transformation.translation([reveal,0,0]) * Geom::Transformation.scaling(ORIGIN,-1.0,1.0,1.0)
          end
          group.transform!(transform)
          group.set_attribute('MHD_DRESSING','WARDROBE_GOLA',true)
          group.set_attribute('MHD_DRESSING','GOLA_PROFILE',shape)
          group.set_attribute('MHD_DRESSING','GOLA_ORIENTATION',@wg_plan['direction'])
          group.set_attribute('MHD_DRESSING','GOLA_INSET_CM',inset/1.cm.to_f)
          group
        end
      ensure
        @wg_building_handle = false
      end
    end

    class << self
      prepend WardrobeGola128 unless ancestors.include?(WardrobeGola128)
    end

    # Generic front coverage includes the remaining main-column front.
    module MixedColumnOverlay131
      def mixed_column_front_targets131(tree,x,inner_width,height,t,c,layout_z,layout_height,door_system)
        return [] unless %w[hinged sliding].include?(door_system.to_s)
        columns = collect_column_regions(tree,x,inner_width,t)
        columns.each_with_index.filter_map do |column,index|
          if @sliding_context && index >= @sliding_context['first'].to_i && index <= @sliding_context['second'].to_i
            next
          end
          node = column['node']
          door = node.is_a?(Hash) ? node['column_door'] : nil
          next unless door.is_a?(Hash) && door['enabled'].to_s == 'yes'
          drawer_top = overlay_drawer_top(node,layout_z,layout_height,t)
          base_bottom = drawer_top ? drawer_top+t/2.0+c : c
          span = opening_door_free_span(node,column['x'],layout_z,column['width'],layout_height,t,base_bottom,height-c,c)
          next unless span && span[1] > span[0]
          {'x0'=>column['x'].to_f,'x1'=>column['x'].to_f+column['width'].to_f,
           'z0'=>span[0].to_f,'z1'=>span[1].to_f,'clearance'=>c.to_f}
        end
      end

      def build_column_doors(root,tree,x,inner_width,height,t,c,door_material,door_system,layout_z=nil,layout_height=nil,data=nil,interior_entities=nil,cabinet_depth=nil,carcass_material=nil)
        previous = @mixed_column_fronts131
        @mixed_column_fronts131 = mixed_column_front_targets131(tree,x,inner_width,height,t,c,
          layout_z || t,layout_height || height-2*t,door_system)
        super
      ensure
        @mixed_column_fronts131 = previous
      end

      def adjacent_horizontal_front_face?(region,regions,side,t)
        return true if super
        return false unless region.is_a?(Hash) && @mixed_column_fronts131
        # Keep the stable kitchen Gola-specific behavior separate.
        return false if active_handle_type == 'gola_reveal' && !wg_enabled?
        x0 = region['x'].to_f; x1 = x0+region['width'].to_f
        @mixed_column_fronts131.any? do |front|
          next false unless [x1,front['x1']].min-[x0,front['x0']].max > 0.15.cm
          if side == :bottom
            boundary = region['z'].to_f-t.to_f/2.0
            (front['z1']-(boundary-front['clearance'])).abs <= 0.01.cm
          else
            boundary = region['z'].to_f+region['height'].to_f+t.to_f/2.0
            (front['z0']-(boundary+front['clearance'])).abs <= 0.01.cm
          end
        end
      end
    end

    class << self
      prepend MixedColumnOverlay131 unless ancestors.include?(MixedColumnOverlay131)
    end

    # Recessed edge handles: independent from carcass Gola and normal handles.
    module RoutedHandles132
      RECESSED_FILENAME132 = 'Recessed Handle.skp'.freeze
      RECESSED_URL132 = "#{DRESSING_SKP_BASE_URL}/Recessed%20Handle.skp".freeze

      def wardrobe_data(item)
        data = super
        data['routed_handle_unit_type'] = 'lower' unless %w[lower upper].include?(data['routed_handle_unit_type'].to_s)
        data['routed_handle_name'] = '' if data['routed_handle_name'].nil?
        data
      end

      def custom_asset_catalogs
        catalog = super
        return catalog unless @rh132_normal_catalog
        catalog.merge('handles'=>Array(catalog['handles']).reject { |r| r.is_a?(Hash) && r['handle_family'].to_s == 'routed' })
      end

      def active_normal_handle_record
        previous = @rh132_normal_catalog
        @rh132_normal_catalog = true
        super
      ensure
        @rh132_normal_catalog = previous
      end

      def routed_handle_unit132
        value = active_front_handle_value('routed_handle_unit_type','lower').to_s
        %w[lower upper].include?(value) ? value : 'lower'
      end

      def routed_handle_record132
        override = @active_front_handle_override
        return nil if override.is_a?(Hash) && override.key?('routed_handle_name') && override['routed_handle_name'].to_s.empty?
        wanted = active_front_handle_value('routed_handle_name','').to_s.strip
        return nil if wanted.empty?
        record = Array(custom_asset_catalogs['handles']).find do |r|
          r.is_a?(Hash) && r['handle_family'].to_s == 'routed' && r['name'].to_s.strip == wanted
        end
        raise "#{MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_DBDC485A4725')}#{wanted}#{MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_09C721B55654')}" unless record
        raise "#{MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_EA5E56C884F7')}#{wanted}#{MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_2898CDF396E1')}" unless File.file?(record['path'].to_s)
        record
      end

      def routed_handle_definition132(model,record)
        if record
          definition = custom_asset_definition(model,record['path'],record['name'])
        else
          @recessed_handle_definitions132 ||= {}
          cached = @recessed_handle_definitions132[model.object_id]
          return cached if cached && cached.valid?
          definition = load_dressing_asset_definition(model,RECESSED_URL132,RECESSED_FILENAME132,File.join(File.dirname(__FILE__),RECESSED_FILENAME132))
          @recessed_handle_definitions132[model.object_id] = definition
        end
        raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_A7EA6447A5BF') unless definition && definition.valid?
        definition
      end

      def routed_handle_profile132(record)
        unit = routed_handle_unit132
        profiles = record.is_a?(Hash) ? record['routed_profiles'] : custom_asset_catalogs['routed_default_profiles']
        profiles = {} unless profiles.is_a?(Hash)
        saved = profiles[unit].is_a?(Hash) ? profiles[unit] : {}
        defaults = {'rot_x'=>0.0,'rot_y'=>0.0,'rot_z'=>0.0,'move_x_cm'=>0.0,'move_y_cm'=>0.0,'move_z_cm'=>0.0,
          'depth_cm'=>0.0,'depth_reference'=>'back','flip_z'=>unit == 'upper'}
        result = defaults.merge(saved)
        result['depth_reference'] = 'back' unless %w[front back center].include?(result['depth_reference'].to_s)
        result
      end

      def routed_with_cut132(height,requested)
        previous = @rh132_cut
        @rh132_cut = effective_handle_cut_for_front(height,requested)
        yield @rh132_cut
      ensure
        @rh132_cut = previous
      end

      def copy_dynamic_door(root,source,name,x,z,w,h,direction,style,path)
        return super unless active_handle_type == 'routed_built_in'
        routed_with_cut132(h,active_handle_cut_height) do |cut|
          super(root,source,name,x,z+(routed_handle_unit132 == 'upper' ? cut : 0.0),w,h,direction,style,path)
        end
      end

      def copy_dynamic_glass_door(root,source,name,x,z,w,h,direction,path)
        return super unless active_handle_type == 'routed_built_in'
        routed_with_cut132(h,active_handle_cut_height) do |cut|
          super(root,source,name,x,z+(routed_handle_unit132 == 'upper' ? cut : 0.0),w,h,direction,path)
        end
      end

      def add_drawer_front(parent,model,name,x,y,z,w,d,h,front_material,back_material,enabled=true,type_override=nil,cut_override=nil)
        type = type_override.to_s
        type = active_handle_type unless %w[none normal gola_reveal routed_built_in].include?(type)
        return super unless enabled && type == 'routed_built_in'
        requested = cut_override.nil? ? active_handle_cut_height : cut_override.to_f
        routed_with_cut132(h,requested) do |cut|
          super(parent,model,name,x,y,z+(routed_handle_unit132 == 'upper' ? cut : 0.0),w,d,h,front_material,back_material,enabled,type_override,cut_override)
        end
      end

      def create_flip_up_door(root,name,x,z,w,h,style,material,path,y)
        return super(root,name,x,z,w,h-effective_handle_cut_for_front(h,active_handle_cut_height),style,material,path,y) if active_handle_type == 'none'
        return super unless active_handle_type == 'routed_built_in'
        routed_with_cut132(h,active_handle_cut_height) do |cut|
          super(root,name,x,z+(routed_handle_unit132 == 'upper' ? cut : 0.0),w,h-cut,style,material,path,y)
        end
      end

      def create_dynamic_glass_flip_up_door(root,source,name,x,z,w,h,path)
        return super(root,source,name,x,z,w,h-effective_handle_cut_for_front(h,active_handle_cut_height),path) if active_handle_type == 'none'
        return super unless active_handle_type == 'routed_built_in'
        routed_with_cut132(h,active_handle_cut_height) do |cut|
          super(root,source,name,x,z+(routed_handle_unit132 == 'upper' ? cut : 0.0),w,h-cut,path)
        end
      end

      def add_biltin_handle_to_front(front,target_width,cut_height,kind='door')
        return nil unless front && front.valid?
        cut = @rh132_cut.nil? ? [cut_height.to_f,0.0].max : @rh132_cut.to_f
        return nil if cut <= 0.001.cm
        model = Sketchup.active_model
        record = routed_handle_record132
        definition = routed_handle_definition132(model,record)
        profile = routed_handle_profile132(record)
        panel = front.definition.bounds
        axes = front.transformation
        ax = axes.xaxis.length.to_f; ay = axes.yaxis.length.to_f; az = axes.zaxis.length.to_f
        raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_CC5F50E65D90') if [ax,ay,az].any? { |v| v <= 0.000001 }
        local_cut = cut/az
        rotation = Geom::Transformation.rotation(ORIGIN,Z_AXIS,profile['rot_z'].to_f.degrees) *
          Geom::Transformation.rotation(ORIGIN,Y_AXIS,profile['rot_y'].to_f.degrees) *
          Geom::Transformation.rotation(ORIGIN,X_AXIS,profile['rot_x'].to_f.degrees)
        child = front.definition.entities.add_instance(definition,rotation)
        force_custom_asset_visible!(child)
        bounds = child.bounds
        raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_421DDE35209B') if bounds.empty? || (bounds.max.x.to_f-bounds.min.x.to_f) <= 0.001 || (bounds.max.z.to_f-bounds.min.z.to_f) <= 0.001
        depth = profile['depth_cm'].to_f
        sy = depth > 0 ? depth.cm/((bounds.max.y.to_f-bounds.min.y.to_f)*ay) : 1.0/ay
        raise MHDESIGN::Language.for_tool('dressing_straight').t('TEXT_93ACAA5EDB0E') unless (bounds.max.y.to_f-bounds.min.y.to_f) > 0.001
        child.transform!(Geom::Transformation.scaling(ORIGIN,target_width.to_f/((bounds.max.x.to_f-bounds.min.x.to_f)*ax),sy,local_cut/(bounds.max.z.to_f-bounds.min.z.to_f)))
        child.transform!(Geom::Transformation.scaling(ORIGIN,1.0,1.0,-1.0)) if profile['flip_z'] == true || profile['flip_z'].to_s == 'yes'
        bounds = child.bounds
        dx = panel.min.x.to_f-bounds.min.x.to_f
        dy = case profile['depth_reference'].to_s
             when 'front' then panel.min.y.to_f-bounds.min.y.to_f
             when 'center' then panel.center.y.to_f-bounds.center.y.to_f
             else panel.max.y.to_f-bounds.max.y.to_f
             end
        dz = routed_handle_unit132 == 'upper' ? panel.min.z.to_f-local_cut-bounds.min.z.to_f : panel.max.z.to_f-bounds.min.z.to_f
        child.transform!(Geom::Transformation.translation([dx+profile['move_x_cm'].to_f.cm/ax,dy+profile['move_y_cm'].to_f.cm/ay,dz+profile['move_z_cm'].to_f.cm/az]))
        force_custom_asset_visible!(child)
        child.name = record ? record['name'].to_s : 'مقبض بلت إن حفر أساسي'
        child.set_attribute('MHD_DRESSING','CUSTOM_ACCESSORY',true)
        child.set_attribute('MHD_DRESSING','CUSTOM_ACCESSORY_KIND','BUILTIN_METAL_HANDLE')
        child.set_attribute('MHD_DRESSING','ROUTED_HANDLE',true)
        child.set_attribute('MHD_DRESSING','PARENT_FRONT',kind.to_s)
        child.set_attribute('MHD_DRESSING','SOURCE_FILE',record ? File.basename(record['path'].to_s) : RECESSED_FILENAME132)
        child.set_attribute('MHD_DRESSING','HANDLE_CUT_CM',cut/1.cm.to_f)
        child.set_attribute('MHD_DRESSING','TARGET_WIDTH_CM',target_width.to_f/1.cm.to_f)
        child.set_attribute('MHD_DRESSING','ROUTED_UNIT_TYPE',routed_handle_unit132)
        set_part_badges(child,['HARDWARE','ACCESSORY','ROUTED_HANDLE'])
        [front,front.definition].each do |owner|
          owner.set_attribute('MHD_DRESSING','ROUTED_HANDLE_CUT_ACTUAL_CM',cut/1.cm.to_f)
          owner.set_attribute('MHD_DRESSING','ROUTED_HANDLE_NAME',record ? record['name'].to_s : RECESSED_FILENAME132)
        end
        child
      rescue
        child.erase! if defined?(child) && child && child.valid?
        raise
      end
    end

    class << self
      prepend RoutedHandles132 unless ancestors.include?(RoutedHandles132)
    end

    module RebatedBack154
      def sides_rebate154?
        data = @active_design_data
        data.is_a?(Hash) && data['back_joint_mode'].to_s == 'rebated' && data['back_rebate_scope'].to_s == 'sides'
      end

      def add_horizontal_grooved_panel(parent,model,name,x,y,z,w,d,h,material,badges=[],face_side=:top)
        data = @active_design_data
        rebate = data.is_a?(Hash) && data['back_joint_mode'].to_s == 'rebated'
        return super unless rebate && Array(badges).include?('MAIN_CARCASS')
        saved = @back_groove_context
        begin
          if sides_rebate154?
            cut = data['back_thickness'].to_f.cm
            raise 'تخانة الضهر لا تترك عمقًا صالحًا للقرصة أو القاعدة.' if d-cut <= 0.1.cm
            @back_groove_context = nil
            super(parent,model,name,x,y,z,w,d-cut,h,material,badges.reject { |b| b == 'BACK_GROOVE' },face_side)
          else
            rear = data['depth'].to_f > 0 ? data['depth'].to_f.cm : y+d
            @back_groove_context = {'enabled'=>true,'y0'=>rear-data['back_thickness'].to_f.cm,'y1'=>rear,'depth'=>data['back_groove_depth'].to_f.cm}
            part = super(parent,model,name,x,y,z,w,d,h,material,badges,face_side)
            part.set_attribute('MHD_DRESSING','BACK_REBATE_SCOPE','all') if part && part.respond_to?(:set_attribute)
            part
          end
        ensure
          @back_groove_context = saved
        end
      end

      def add_sloped_relief_top(parent,model,name,total,depth,t,material,spans)
        data = @active_design_data
        return super unless data.is_a?(Hash) && data['back_joint_mode'].to_s == 'rebated'
        bt = data['back_thickness'].to_f.cm
        return super(parent,model,name,total,depth-bt,t,material,spans) if sides_rebate154?
        part = super
        rise = slope_height_at(total)-slope_height_at(0)
        length = Math.sqrt(total*total+rise*rise)
        shift = -t*rise/total
        points = [[shift,depth-bt,-t],[shift+length,depth-bt,-t],[shift+length,depth,-t],[shift,depth,-t]]
        face = part.definition.entities.add_face(points)
        raise 'تعذر تنفيذ تفريزة القرصة المائلة.' unless face
        face.reverse! if face.normal.z > 0
        face.pushpull(-[data['back_groove_depth'].to_f.cm,t-0.01.cm].min)
        part
      end
    end
    class << self
      prepend RebatedBack154 unless ancestors.include?(RebatedBack154)
    end

    module LappedBack155
      def lapped_back155?(data = @active_design_data)
        data.is_a?(Hash) && data['back_joint_mode'].to_s == 'lapped'
      end

      def lapped_shell_depth155(depth,data)
        result = depth-data['back_thickness'].to_f.cm
        raise 'تخانة الضهر لا تترك عمقًا صالحًا للشاسيه.' if result <= data['thickness'].to_f.cm
        result
      end

      def build_straight_grooved_shell(entities,model,total,depth,height,t,material,data)
        return super unless lapped_back155?(data)
        super(entities,model,total,lapped_shell_depth155(depth,data),height,t,material,data)
      end

      def build_sloped_shell(entities,model,total,depth,t,bt,bi,material,back_material,data)
        return super unless lapped_back155?(data)
        super(entities,model,total,lapped_shell_depth155(depth,data),t,bt,0.0,material,back_material,data)
      end

      def build_fixed_glass_sides(root,entities,model,total,depth,height,t,data)
        return super unless lapped_back155?(data)
        super(root,entities,model,total,lapped_shell_depth155(depth,data),height,t,data)
      end

      def build_visible_side_panels(entities,model,total,depth,height,t,carcass,door,data)
        return super unless lapped_back155?(data)
        super(entities,model,total,lapped_shell_depth155(depth,data),height,t,carcass,door,data)
      end

      def build_column_backs(entities,model,regions,total,depth,height,t,bt,bi,material,data)
        return super unless lapped_back155?(data)
        y = depth-bt
        raise 'تخانة الضهر أكبر من العمق المتاح.' if y <= 0
        name = "ضهر لطش كامل #{PART_SUFFIX}"
        if slope_enabled?(data)
          add_xz_prism(entities,model,name,[[0,0],[total,0],[total,slope_height_at(total)],[0,slope_height_at(0)]],y,bt,material,['BACK_PANEL','COLUMN_BACK','SLOPED'])
        else
          add_box_without_wall_relief(entities,model,name,0,y,0,total,bt,height,material,['BACK_PANEL','COLUMN_BACK'])
        end
      end
    end
    class << self
      prepend LappedBack155 unless ancestors.include?(LappedBack155)
    end

