        :copy_dynamic_door                 => 'dynamic_door',
        :copy_dynamic_glass_door           => 'dynamic_glass_door',
        :create_sloped_dynamic_door        => 'sloped_dynamic_door'
      }.freeze

      PERF_METHODS.each do |method_name, label|
