# Step166: actual miter endpoints, preserving existing groove and relief cross-sections.
module MHDESIGN
  module DressingDesigner
    module MiterAssembly166
      def side_extension_for(data)
        if data['joinery_system'].to_s == 'miter45' &&
           (miter_option167?(data, 'miter_base', 'yes') ||
            (data['base_type'] == 'wood_plinth' && miter_option167?(data, 'miter_plinth', 'yes')))
          return 0.0
        end
        super
      end

      def build_straight_grooved_shell(entities,model,total,depth,height,t,material,data)
        return super unless data['joinery_system'].to_s == 'miter45'
        raise 'تجميع 45 مخصص للأجناب الخشب، وليس الأجناب الزجاج.' if glass_side?(data,'left') || glass_side?(data,'right')
        previous = @miter_shell166
        @miter_shell166 = {width:total.to_f,height:height.to_f,data:data}
        begin
          super
        ensure
          @miter_shell166 = previous
        end
      end

      def build_sloped_shell(entities,model,total,depth,t,bt,bi,material,back_material,data)
        raise 'تجميع 45 يحتاج قرصة أفقية. غيّر نظام التجميع للوحدة المائلة.' if data['joinery_system'].to_s == 'miter45'
        super
      end

      def add_vertical_panel(parent,model,name,x,y,z,w,d,h,material,badges=[],side=nil)
        part=super
        return part unless @miter_shell166 && Array(badges).include?('MAIN_CARCASS')
        miter_part166(part,:side,x,z,w,h)
      end

      def add_horizontal_grooved_panel(parent,model,name,x,y,z,w,d,h,material,badges=[],face_side=:top)
        part=super
        return part unless @miter_shell166 && Array(badges).include?('MAIN_CARCASS')
        miter_part166(part,:horizontal,x,z,w,h)
      end
    end
    class << self
      prepend MiterAssembly166 unless ancestors.include?(MiterAssembly166)
    end
  end
end

# Step167: Independent miter settings for cabinet pieces, plinth and drawer frames.
module MHDESIGN
  module DressingDesigner
    module MiterChoices167
      def miter_option167?(data, key, default = 'no')
        data.is_a?(Hash) && data['joinery_system'].to_s == 'miter45' && data.fetch(key, default).to_s == 'yes'
      end

      def shell_miter_joint167?(data, side, rail)
        miter_option167?(data, "miter_#{side}", 'yes') && miter_option167?(data, "miter_#{rail}", 'yes')
      end

      def miter_point166(point, kind, x, z, width, height)
        px, py, pz = point.map(&:to_f)
        shell = @miter_shell166
        if kind == :side
          side = x < shell[:width] / 2.0 ? 'left' : 'right'
          inset = side == 'left' ? px - x : x + width - px
          pz += inset if shell_miter_joint167?(shell[:data], side, 'base') && (pz-z).abs < 0.00001
          pz -= inset if shell_miter_joint167?(shell[:data], side, 'top') && (point[2].to_f-z-height).abs < 0.00001
        else
          base = z < shell[:height] / 2.0
          rail = base ? 'base' : 'top'
          inset = base ? pz-z : z+height-pz
          px += inset if shell_miter_joint167?(shell[:data], 'left', rail) && (px-x).abs < 0.00001
          px -= inset if shell_miter_joint167?(shell[:data], 'right', rail) && (point[0].to_f-x-width).abs < 0.00001
        end
        [px, py, pz]
      end

      def mark_miter167(part, ends)
        [part, part.definition].each do |owner|
          owner.set_attribute('MHD_DRESSING', 'MITER_ANGLE', 45)
          owner.set_attribute('MHD_DRESSING', 'MITER_ENDS', ends.length == 2 ? 'both' : ends.first.to_s)
        end
        part
      end

      def deform_miter167(part, ends)
        return part if !part || ends.empty?
        part.make_unique
        entities = part.definition.entities
        transform = part.transformation
        inverse = transform.inverse
        vertices = entities.grep(Sketchup::Edge).flat_map(&:vertices).uniq
        vectors = vertices.map do |vertex|
          original = vertex.position
          coordinates = original.transform(transform).to_a
          target = Geom::Point3d.new(yield(coordinates)).transform(inverse)
          target - original
        end
        entities.transform_by_vectors(vertices, vectors)
        mark_miter167(part, ends)
      end

      def miter_part166(part, kind, x, z, width, height)
        data = @miter_shell166[:data]
        if kind == :side
          side = x < @miter_shell166[:width] / 2.0 ? 'left' : 'right'
          ends = %w[base top].select { |rail| shell_miter_joint167?(data, side, rail) }
        else
          rail = z < @miter_shell166[:height] / 2.0 ? 'base' : 'top'
          ends = %w[left right].select { |side| shell_miter_joint167?(data, side, rail) }
        end
        deform_miter167(part, ends) { |point| miter_point166(point, kind, x, z, width, height) }
      end

      def bevel_xy_endpoints167(part, axis, origin, length, ends)
        deform_miter167(part, ends) do |point|
          coordinate = point[axis].to_f
          inset = yield(point).to_f
          point[axis] = coordinate + inset if ends.include?(:start) && (coordinate-origin).abs < 0.00001
          point[axis] = coordinate - inset if ends.include?(:end) && (coordinate-origin-length).abs < 0.00001
          point
        end
      end

      def add_drawer_side_with_bottom_groove(*args, miter_ends: [])
        part = super(*args)
        return part if miter_ends.empty?
        x, y, _, width, depth = args[3,5]
        left = args.last == :max_x
        bevel_xy_endpoints167(part, 1, y, depth, miter_ends) do |point|
          left ? point[0]-x : x+width-point[0]
        end
      end

      def add_drawer_cross_with_bottom_groove(*args, miter_ends: [])
        part = super(*args)
        return part if miter_ends.empty?
        x, y, _, width, depth = args[3,5]
        front = args.last == :max_y
        bevel_xy_endpoints167(part, 0, x, width, miter_ends) do |point|
          front ? point[1]-y : y+depth-point[1]
        end
      end

      def miter_rail167(entities, model, name, x, y, z, width, depth, height, material, badges, front, left, right)
        part = add_box_without_wall_relief(entities,model,name,x,y,z,width,depth,height,material,badges)
        ends = []
        ends << :start if left
        ends << :end if right
        bevel_xy_endpoints167(part, 0, x, width, ends) do |point|
          front ? point[1]-y : y+depth-point[1]
        end
      end

      def miter_plinth_side167(entities,model,name,x,y,z,width,depth,height,material,badges,left,rear)
        part = add_box_without_wall_relief(entities,model,name,x,y,z,width,depth,height,material,badges)
        ends = rear ? [:start, :end] : [:start]
        bevel_xy_endpoints167(part, 1, y, depth, ends) do |point|
          left ? point[0]-x : x+width-point[0]
        end
      end

      # The outer drawer frame has a separate cap and four short ties.
      # Miter the joints between those ties and the two upright side boards.
      def outer_frame_side_profile167(thickness, depth, covered)
        if covered
          [[0,0],[thickness,thickness],[thickness,depth-thickness],[0,depth]]
        else
          [[0,0],[2*thickness,0],[2*thickness,depth],[0,depth],
           [thickness,depth-thickness],[thickness,thickness]]
        end
      end

      def outer_frame_tie_profile167(width, thickness, front)
        return [[0,0],[width-thickness,0],[width,thickness],[0,thickness]] if front
        [[0,0],[width,0],[width-thickness,thickness],[0,thickness]]
      end

      def add_outer_drawer_frame_part167(entities,model,name,x,y,z,width,depth,height,material,badges,profile,left)
        points = left ? profile : profile.reverse.map { |px, py| [width-px, py] }
        part = add_xy_profile(entities,model,name,points,x,y,z,width,depth,height,material,badges)
        mark_miter167(part, badges.include?('MITER_DRAWER_SIDE') ? [:start,:end] : [left ? :end : :start])
      end
    end
    class << self
      prepend MiterChoices167 unless ancestors.include?(MiterChoices167)
    end
  end
end

module MHDESIGN
  module DressingDesigner
    extend self

    QUICK_OPTION_LENGTHS = {
      'a1'=>'width', 'a2'=>'depth', 'a3'=>'height',
      'base_unit_1_a'=>'leg_height', 'base_unit_1_d'=>'thickness'
    }.freeze
    QUICK_OPTION_MATERIALS = {
      'base_unit_1_f'=>'door_material', 'base_unit_1_j'=>'material', 'base_unit_1_h'=>'back_material'
    }.freeze

    class StraightQuickOptionsObserver < Sketchup::ModelObserver
      def onTransactionCommit(model)
        return if MHDESIGN::DressingDesigner.quick_options_busy?
        root = model.selection.first
        return unless model.selection.length == 1 && root.is_a?(Sketchup::ComponentInstance)
        return unless root.get_attribute('MHD_DRESSING', 'QUICK_OPTIONS_BASELINE')
        UI.start_timer(0, false) { MHDESIGN::DressingDesigner.apply_straight_quick_options(model, root) }
      end
    end

    class StraightQuickOptionsAppObserver < Sketchup::AppObserver
      def onOpenModel(model)
        MHDESIGN::DressingDesigner.observe_straight_quick_options(model)
      end

      alias onNewModel onOpenModel
    end

    def observe_straight_quick_options(model)
      observer = (@straight_quick_options_observer ||= StraightQuickOptionsObserver.new)
      model.add_observer(observer) if model
    end

    def quick_options_busy?
      @straight_quick_options_busy
    end

    def drawer_quick_fields(data)
      node = data['layout_tree']
      return {} unless node.is_a?(Hash) && !node['dir'] && node['type'] == 'drawers'
      return {} if [node['column_door'], node['opening_door']].any? { |door| door.is_a?(Hash) && door['enabled'] == 'yes' }
      count = node['count'].to_i
      return {} unless count.between?(1, 32)
      overlay = node['drawer_pattern'] == 'overlay_front'
      stack = (data['height'].to_f - 2 * data['thickness'].to_f).cm
      heights = drawer_nominal_front_heights(node, count, stack, (node['front_gap'] || 0.3).to_f.cm)
      fields = {}
      (1..count).each do |index|
        visible = !drawer_hidden?(node, index, count)
        prefix = format('base_unit_1_al_drawer_%02d', index)
        fields[prefix+'_a_state'] = [index, 'hidden', "حالة الدرج #{index}", {'مرئي'=>'visible', 'مخفي'=>'hidden'}, visible ? 'visible' : 'hidden'] if overlay && index < count
        if visible
          fields[prefix+'_b_face'] = [index, 'face', "ارتفاع وش الدرج #{index}", nil, heights.fetch(index).to_f / 1.cm]
        end
        height = drawer_chassis_height_for(node, index, (node['chassis_height'] || 13).to_f.cm)
        height = drawer_hidden_chassis_height(node, index, height) unless visible
        fields[prefix+'_c_chassis'] = [index, 'chassis', "ارتفاع شاسيه الدرج #{index}", nil, height / 1.cm]
        accessory = node['accessory_items'].is_a?(Hash) ? node['accessory_items']["drawer:#{index}"] : nil
        accessory = {} unless accessory.is_a?(Hash)
        custom = drawer_custom_record143(accessory)
        unless custom
          fields[prefix+'_d_runner'] = [index, 'runner', "نوع مجرى الدرج #{index}",
            {'بدون مجرى'=>'none', 'مجرى جانبي'=>'side', 'مجرى سفلي'=>'under'},
            drawer_runner_type143(node, accessory)]
        end
      end
      fields
    end

    def quick_option_values(root)
      lengths = QUICK_OPTION_LENGTHS.transform_values { nil }
      lengths.each_key { |key| lengths[key] = dc_value(root, key, 0).to_f * 2.54 }
      QUICK_OPTION_MATERIALS.each_key do |key|
        lengths[key] = dc_list_current_value(root, key, '').to_s
      end
      if root.definition.get_attribute('dynamic_attributes', '_base_unit_1_aa_mhd_type_options')
        lengths['base_unit_1_aa_mhd_type'] = dc_value(root, 'base_unit_1_aa_mhd_type', 'legs').to_s
      end
      QUICK_EXTRA_OPTIONS.each do |key, (_field, _label, choices)|
        next if root.get_attribute('dynamic_attributes', "_#{key}_access", 'NONE') == 'NONE'
        value = dc_value(root, key, choices ? '' : 0)
        lengths[key] = choices ? value.to_s : value.to_f * 2.54
      end
      saved = JSON.parse(root.get_attribute('MHD_DRESSING', 'DATA_JSON'))
      drawer_quick_fields(saved).each do |key, (_index, _field, _label, choices, default)|
        value = dc_value(root, key, choices ? default : default.to_f / 2.54)
        lengths[key] = choices ? value.to_s : value.to_f * 2.54
      end
      lengths
    end

    QUICK_OPTION_FIELDS = [
      ['a1', 'عرض الشاسيه', 'TEXTBOX'],
      ['a2', 'عمق الشاسيه', 'TEXTBOX'],
      ['a3', 'ارتفاع الشاسيه', 'TEXTBOX'],
      ['base_unit_1_a', 'ارتفاع الرجول / الوزر', 'TEXTBOX'],
      ['base_unit_1_aa_mhd_type', 'نوع القاعدة', 'LIST'],
      ['base_unit_1_d', 'تخانة الكونتر', 'TEXTBOX'],
      ['base_unit_1_f', 'خامة الضلفة', 'LIST'],
      ['base_unit_1_j', 'خامة الشاسيه', 'LIST'],
      ['base_unit_1_h', 'خامة الضهر', 'LIST']
    ].freeze

    QUICK_EXTRA_OPTIONS = {
      'base_unit_1_ab_assembly'=>['assembly', 'طريقة التجميع', {'جنب على القاعدة'=>'on_base', 'جنب كامل'=>'full'}],
      'base_unit_1_ac_top_body'=>['top_structure_type', 'نوع القرصة', {'قرصة كاملة'=>'full_panel', 'شدادات'=>'stretchers'}],
      'base_unit_1_ad_top_joint'=>['top_type', 'تجميع القرصة', {'قرصة بين الجنبين'=>'between_sides', 'قرصة كاملة'=>'full_top'}],
      'base_unit_1_ae_visible_side'=>['visible_side_direction', 'جنب ظاهر', {'لا'=>'none', 'يمين'=>'right', 'شمال'=>'left', 'الاتجاهين'=>'both'}],
      'base_unit_1_af_back_inset'=>['back_inset', 'بداية الضهر من الخلف', nil],
      'base_unit_1_ag_back_thickness'=>['back_thickness', 'تخانة الضهر', nil],
      'base_unit_1_ah_back_groove'=>['back_groove_depth', 'سقوط المفحار', nil],
      'base_unit_1_ai_shelf_cut'=>['shelf_front_cut', 'قص الرف من الأمام', nil],
      'base_unit_1_aj_handle'=>['handle_type', 'نوع الضلفة', {'بدون مقبض'=>'none', 'مقبض عادي'=>'normal', 'مقبض بلت إن بخلع'=>'gola_reveal', 'مقبض بلت إن حفر'=>'routed_built_in'}],
      'base_unit_1_ak_door_gap'=>['door_clearance', 'خلوص الضلفة', nil]
    }.freeze

    def quick_handle_unit(data)
      key = {'normal'=>'normal_handle_unit_type', 'gola_reveal'=>'gola_unit_type',
             'routed_built_in'=>'routed_handle_unit_type'}[data['handle_type']]
      return data['quick_handle_unit'] if %w[lower upper wardrobe].include?(data['quick_handle_unit'])
      return 'upper' if data['handle_type'] == 'bottom_lip'
      key && data[key]
    end

    def prepare_quick_options(root, data)
      extras = QUICK_EXTRA_OPTIONS.reject do |_key, (field, _label, _choices)|
        (field == 'back_inset' && %w[rebated lapped].include?(data['back_joint_mode'])) ||
          (field == 'back_groove_depth' && data['back_joint_mode'] == 'lapped') ||
          (field == 'handle_type' && !%w[lower upper wardrobe].include?(quick_handle_unit(data)))
      end
      drawers = drawer_quick_fields(data)
      fields = QUICK_OPTION_FIELDS.dup
      fields.concat(drawers.map { |key, (_index, _field, label, choices, _value)| [key, label, choices ? 'LIST' : 'TEXTBOX'] })
      drawers.each do |key, (_index, _field, _label, choices, value)|
        if choices
          options = choices.map { |label, id| "#{label.codepoints.map { |code| format('%%u%04X', code) }.join}=#{id}" }
          [root, root.definition].each { |owner| owner.set_attribute('dynamic_attributes', "_#{key}_options", "&#{options.join('&')}&") }
          apply_dc_list_value(root, key, value)
        else
          set_dc_cm(root, key, value)
          root.definition.set_attribute('dynamic_attributes', "_#{key}_units", 'CENTIMETERS')
          root.definition.set_attribute('dynamic_attributes', "_#{key}_formulaunits", 'CENTIMETERS')
        end
      end
      fields.insert(5, *extras.map { |key, (_field, label, choices)| [key, label, choices ? 'LIST' : 'TEXTBOX'] })
      extras.each do |key, (field, _label, choices)|
        value = data[field]
        if choices
          choices = choices.merge('بشفّة من الأسفل'=>'bottom_lip') if field == 'handle_type' && quick_handle_unit(data) == 'upper'
          value = 'none' if field == 'visible_side_direction' && data['side_state'] != 'visible'
          value = choices.values.first unless choices.value?(value)
          encoded = choices.map { |label, id| "#{label.codepoints.map { |code| format('%%u%04X', code) }.join}=#{id}" }
          [root.definition, root].each do |owner|
            owner.set_attribute('dynamic_attributes', "_#{key}_options", "&#{encoded.join('&')}&")
          end
          apply_dc_list_value(root, key, value)
        else
          set_dc_cm(root, key, value)
          root.definition.set_attribute('dynamic_attributes', "_#{key}_units", 'CENTIMETERS')
          root.definition.set_attribute('dynamic_attributes', "_#{key}_formulaunits", 'CENTIMETERS')
        end
      end
      dictionary = 'dynamic_attributes'
      exposed = fields.map(&:first)
      choices = {'رجول — كما هي في الوحدة'=>'legs', 'سوكلو خشب'=>'wood_plinth'}
      options = choices.map do |label, value|
        encoded_label = label.codepoints.map { |code| format('%%u%04X', code) }.join
        "#{encoded_label}=#{value}"
      end.join('&')
      [root.definition, root].each do |owner|
        attributes = owner.attribute_dictionary(dictionary, false)
        Array(attributes && attributes.keys).each do |name|
          next unless name.start_with?('_') && name.end_with?('_access')
          next if exposed.include?(name[1...-7])
          owner.set_attribute(dictionary, name, 'NONE')
        end

        owner.set_attribute(dictionary, '_base_unit_1_aa_mhd_type_options', "&#{options}&")
        fields.each_with_index do |(key, label, access), index|
          owner.set_attribute(dictionary, "_#{key}_access", access)
          owner.set_attribute(dictionary, "_#{key}_formlabel", label)
          owner.set_attribute(dictionary, "_#{key}_label", label)
          owner.set_attribute(dictionary, "_#{key}_order", index + 1)
        end
      end
      root.definition.set_attribute('MHD_DRESSING', 'STRAIGHT_OPTIONS_SCHEMA', 1)
    end

    def store_quick_options_baseline(root)
      prepare_quick_options(root, JSON.parse(root.get_attribute('MHD_DRESSING', 'DATA_JSON')))
      if root.definition.get_attribute('dynamic_attributes', '_base_unit_1_aa_mhd_type_options')
        saved = JSON.parse(root.get_attribute('MHD_DRESSING', 'DATA_JSON'))
        apply_dc_list_value(root, 'base_unit_1_aa_mhd_type', saved['base_type'] == 'wood_plinth' ? 'wood_plinth' : 'legs')
      end
      root.set_attribute('MHD_DRESSING', 'QUICK_OPTIONS_BASELINE', JSON.generate(quick_option_values(root)))
    end

    def quick_option_locked_tree?(node, key)
      node.is_a?(Hash) && (node[key].to_f > 0 ||
        Array(node['children']).any? { |child| quick_option_locked_tree?(child, key) })
    end

    def apply_straight_quick_options(model, root)
      return if quick_options_busy? || model != Sketchup.active_model || !root.valid?
      return if @dialog && @dialog.visible?
      previous_root = @current_wardrobe
      baseline = JSON.parse(root.get_attribute('MHD_DRESSING', 'QUICK_OPTIONS_BASELINE'))
      current = quick_option_values(root)
      changes = current.reject do |key, value|
        value.is_a?(Numeric) ? (value-baseline.fetch(key, value).to_f).abs < 0.001 : value == baseline[key]
      end
      return if changes.empty?

      @straight_quick_options_busy = true
      saved = wardrobe_data(root)
      data = JSON.parse(JSON.generate(saved))
      if changes.key?('base_unit_1_aa_mhd_type')
        target_base = changes.delete('base_unit_1_aa_mhd_type')
        if %w[legs wood_plinth].include?(target_base)
          data['base_type'] = target_base
          changes['base_unit_1_a'] = current.fetch('base_unit_1_a')
        end
      end
      drawer_fields = drawer_quick_fields(saved)
      node = data['layout_tree']
      changes.each do |key, value|
        if drawer_fields.key?(key)
          index, field = drawer_fields.fetch(key)
          index = index.to_s
          case field
          when 'hidden'
            record = ((node['drawer_hidden_overrides'] ||= {})[index] ||= {})
            record['hidden'] = value == 'hidden' ? 'yes' : 'no'
          when 'face'
            (node['drawer_height_overrides'] ||= {})[index] = [value, 4.0].max
          when 'runner'
            if %w[none side under].include?(value)
              accessory = ((node['accessory_items'] ||= {})["drawer:#{index}"] ||= {})
              accessory['runner_type'] = value
            end
          when 'chassis'
            (node['drawer_chassis_height_overrides'] ||= {})[index] = [value, 1.0].max
            record = drawer_hidden_override(node, index)
            record['chassis_height'] = [value, 1.0].max unless record.empty?
          end
          next
        end
        field = QUICK_OPTION_LENGTHS[key] || QUICK_OPTION_MATERIALS[key] || QUICK_EXTRA_OPTIONS.fetch(key).first
        if field == 'visible_side_direction'
          data['side_state'] = value == 'none' ? 'none' : 'visible'
          data['visible_side_material'] = '__door__'
          next if value == 'none'
        end
        field = 'wood_plinth_height' if field == 'leg_height' && data['base_type'] == 'wood_plinth'
        data[field] = value
      end
      @current_wardrobe = root
      begin
        if changes.key?('base_unit_1_aj_handle')
          unit = quick_handle_unit(saved)
          type = data['handle_type']
          if type != 'none' && (!%w[lower upper wardrobe].include?(unit) ||
              (unit == 'wardrobe' && type == 'routed_built_in') ||
              (type == 'bottom_lip' && unit != 'upper'))
            raise 'حدد المقبض ونوع الوحدة من الدريسنج الأول.'
          end
          data['quick_handle_unit'] = unit if unit
          unit_key = {'normal'=>'normal_handle_unit_type', 'gola_reveal'=>'gola_unit_type',
                      'routed_built_in'=>'routed_handle_unit_type'}[type]
          data[unit_key] = unit if unit_key
        end
        if %w[width height].any? { |field| data[field] != saved[field] && quick_option_locked_tree?(data['layout_tree'], "#{field}_lock_cm") }
          raise 'المقاس فيه قفل. عدّله من واجهة الدريسنج عشان توزيع المقاسات.'
        end
        create_dressing(data)
      rescue StandardError => error
        model.start_operation('استرجاع خيارات الدريسنج', true)
        begin
          QUICK_OPTION_LENGTHS.each_key { |key| set_dc_cm(root, key, baseline.fetch(key)) }
          QUICK_OPTION_MATERIALS.each_key { |key| apply_dc_list_value(root, key, baseline.fetch(key)) }
          QUICK_EXTRA_OPTIONS.each do |key, (_field, _label, choices)|
            next unless baseline.key?(key)
            choices ? apply_dc_list_value(root, key, baseline[key]) : set_dc_cm(root, key, baseline[key])
          end
          drawer_fields.each do |key, (_index, _field, _label, choices, _value)|
            next unless baseline.key?(key)
            choices ? apply_dc_list_value(root, key, baseline[key]) : set_dc_cm(root, key, baseline[key])
          end
          if baseline.key?('base_unit_1_aa_mhd_type')
            apply_dc_list_value(root, 'base_unit_1_aa_mhd_type', baseline.fetch('base_unit_1_aa_mhd_type'))
          end
          redraw_dc(root)
          model.commit_operation
        rescue StandardError
          model.abort_operation
          raise
        end
        UI.messagebox("تعذر تطبيق التعديل السريع. #{error.message}")
      ensure
        @current_wardrobe = previous_root
        @straight_quick_options_busy = false
      end
    end

    unless @straight_quick_options_app_observer
      @straight_quick_options_app_observer = StraightQuickOptionsAppObserver.new
      Sketchup.add_observer(@straight_quick_options_app_observer)
      observe_straight_quick_options(Sketchup.active_model)
    end
  end
end
